window.QB_TKP_B14 = [
{id:"TKP-2201", q:"Seorang pengusaha menawarkan Anda amplop berisi uang agar perizinan usahanya dipercepat, padahal berkasnya belum lengkap. Ia berdalih 'ini sekadar tanda terima kasih'. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan tegas dan sopan, menjelaskan prosedur yang benar, serta melaporkan upaya penyuapan ke atasan/inspektorat", s:5},{t:"Menolak amplop tersebut dan memintanya melengkapi berkas sesuai prosedur", s:4},{t:"Berpura-pura tidak mendengar tawarannya dan melanjutkan tugas seperti biasa", s:3},{t:"Menolak amplop tetapi tetap memberi tahu celah agar berkasnya cepat lolos", s:2},{t:"Menerima amplop dan langsung menerbitkan izin tanpa memeriksa berkas", s:1}], ex:"Menolak gratifikasi dan melaporkannya adalah wujud integritas; menerima dalam bentuk apa pun melanggar UU Tipikor dan kode etik ASN."},
{id:"TKP-2202", q:"Atasan Anda, Pak Hendra, meminta Anda memasukkan nama keponakannya ke daftar penerima bantuan sosial padahal tidak memenuhi syarat. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan santun, menunjukkan kriteria resmi penerima, serta mencatat/melaporkan permintaan tersebut sesuai jalur", s:5},{t:"Menolak memasukkan namanya dan tetap berpegang pada kriteria resmi", s:4},{t:"Menyerahkan keputusan sepenuhnya kepada atasan tanpa berkomentar", s:3},{t:"Menolak terang-terangan tetapi diam-diam menunda pemrosesan berkas lain sebagai balasan", s:2},{t:"Menuruti permintaan atasan demi menjaga hubungan baik", s:1}], ex:"Konflik kepentingan dari atasan harus ditolak dan dilaporkan; integritas mengharuskan ASN mengutamakan aturan di atas perintah yang menyimpang."},
{id:"TKP-2203", q:"Rekan kerja Anda, Siti, sering datang terlambat dan pulang lebih awal tetapi tetap mencatat kehadiran penuh. Pimpinan tidak menegur. Sikap yang paling tepat adalah ....", opts:[{t:"Menegur Siti secara pribadi dengan baik, menjelaskan kewajiban disiplin, dan melaporkannya bila tidak berubah", s:5},{t:"Mengingatkan Siti bahwa perilakunya melanggar disiplin dan bisa merugikan tim", s:4},{t:"Tidak ikut-ikutan dan tidak mencampuri urusan orang lain", s:3},{t:"Meminta Siti membagi 'jatah' keuntungan dari waktu luangnya agar Anda diam", s:2},{t:"Ikut meniru karena merasa pimpinan tidak peduli", s:1}], ex:"Disiplin adalah kewajiban ASN; menegur lalu melaporkan pelanggaran disiplin rekan adalah wujud tanggung jawab, bukan ikut larut."},
{id:"TKP-2204", q:"Di grup chat kantor, seorang rekan membagikan konten yang menyebut kelompok agama tertentu sebagai musuh dan mengajak membenci mereka. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menyebarkan, menegur pengirim dengan santun, dan melaporkan konten intoleran tersebut ke atasan atau pihak berwenang", s:5},{t:"Tidak ikut menyebarkan dan menegur pengirim agar tidak mengulanginya", s:4},{t:"Membiarkannya karena bukan urusan Anda", s:3},{t:"Ikut meneruskan ke grup lain agar terlihat kompak dengan rekan", s:2},{t:"Menambah-nambahi komentar kebencian agar diterima kelompok", s:1}], ex:"ASN wajib menjaga toleransi dan nasionalisme; menyebarkan paham intoleran/radikal melanggar kode etik dan bisa dipidana UU ITE."},
{id:"TKP-2205", q:"Menjelang pemilu, calon legislatif meminta Anda mengajak warga di wilayah kerja Anda memilihnya dan menjanjikan imbalan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak tegas, menjelaskan asas netralitas ASN, dan melaporkan upaya politisasi tersebut", s:5},{t:"Menolak ajakannya dan tetap bersikap netral dalam bertugas", s:4},{t:"Tidak menjawab dan menghindar setiap kali diajak bicara soal pemilu", s:3},{t:"Menolak imbalan tetapi diam-diam memberi tahu warga soal calon tersebut", s:2},{t:"Menerima tawaran karena menguntungkan secara pribadi", s:1}], ex:"Netralitas ASN dalam pemilu adalah kewajiban UU ASN; ikut berkampanye atau menerima imbalan politik adalah pelanggaran berat."},
{id:"TKP-2206", q:"Anda menemukan bukti bahwa proyek pengadaan di dinas Anda fiktif — barang tidak pernah ada tetapi anggaran sudah cair. Sikap yang paling tepat adalah ....", opts:[{t:"Mengumpulkan bukti dan melaporkannya melalui whistleblowing system (WBS)/inspektorat/APIP", s:5},{t:"Menyimpan bukti dan menyampaikannya langsung kepada pimpinan tertinggi", s:4},{t:"Diam saja karena takut dianggap pengkhianat oleh rekan", s:3},{t:"Meminta bagian dari dana proyek agar Anda ikut diam", s:2},{t:"Ikut menandatangani dokumen pencairan agar tidak dicurigai", s:1}], ex:"Whistleblowing melalui WBS adalah mekanisme resmi perlindungan pelapor; membiarkan korupsi fiktif berarti ikut bertanggung jawab."},
{id:"TKP-2207", q:"Warga bernama Ibu Ratna menawarkan Anda parsel lebaran agar surat keterangannya diproses lebih dulu dari antrean. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak parsel, menjelaskan antrean berlaku adil untuk semua, dan tetap melayani sesuai urutan", s:5},{t:"Menolak parsel dan memintanya antre seperti warga lain", s:4},{t:"Menerima parsel tetapi tetap memproses sesuai antrean", s:3},{t:"Menolak parsel tetapi menyelipkan berkasnya ke urutan depan", s:2},{t:"Menerima parsel dan memprioritaskan berkasnya", s:1}], ex:"Gratifikasi dalam bentuk apa pun — termasuk parsel — dilarang; pelayanan publik harus adil tanpa perlakuan istimewa."},
{id:"TKP-2208", q:"Atasan Anda menyuruh mengubah angka laporan keuangan agar terlihat tidak ada sisa anggaran yang harus dikembalikan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak memalsukan laporan, menjelaskan risikonya, dan melaporkan perintah menyimpang tersebut ke inspektorat", s:5},{t:"Menolak mengubah angka dan menyajikan laporan sesuai data sebenarnya", s:4},{t:"Menunda-nunda pengerjaan laporan dengan harapan perintah dibatalkan", s:3},{t:"Mengubah sebagian kecil saja agar tidak terlalu mencolok", s:2},{t:"Menuruti perintah karena itu perintah atasan", s:1}], ex:"Perintah atasan yang melanggar hukum wajib ditolak; memalsukan laporan keuangan adalah tindak pidana korupsi."},
{id:"TKP-2209", q:"Seorang rekan di kecamatan Anda giat menyebarkan pamflet ajakan mengganti ideologi negara di lingkungan kantor. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak paham tersebut, menegur rekan, dan melaporkannya ke pimpinan/aparat karena bertentangan dengan Pancasila", s:5},{t:"Menolak ikut serta dan menjauhi kegiatan penyebarannya", s:4},{t:"Pura-pura tidak melihat agar tidak bermusuhan", s:3},{t:"Menyimpan pamfletnya tetapi tidak menyebarkannya", s:2},{t:"Ikut menyebarkan karena takut dikucilkan kelompoknya", s:1}], ex:"Nasionalisme ASN menuntut pembelaan Pancasila; paham ekstrem anti-ideologi negara wajib dilaporkan, bukan didiamkan."},
{id:"TKP-2210", q:"Petugas loket di kantor Anda, Agus, kerap meminta 'uang rokok' kepada pemohon KTP. Warga sudah banyak mengeluh. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan pungli tersebut ke atasan/inspektorat disertai bukti keluhan warga", s:5},{t:"Menegur Agus secara langsung agar menghentikan punglinya", s:4},{t:"Tidak terlibat dan menganggap itu urusan Agus sendiri", s:3},{t:"Menasihati warga agar memberi saja supaya urusannya cepat", s:2},{t:"Ikut meminta bagian karena Anda satu loket dengannya", s:1}], ex:"Pungli adalah korupsi; ASN yang mengetahui wajib melaporkannya, bukan menoleransi apalagi ikut menikmati."},
{id:"TKP-2211", q:"Anda diminta panitia menjadi bendahara kegiatan kantor. Di akhir acara ada sisa dana yang tidak tercatat. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan sisa dana secara transparan kepada panitia dan mengembalikannya ke kas resmi", s:5},{t:"Mengembalikan sisa dana ke kas tanpa memberitahu siapa pun", s:4},{t:"Menyimpannya dulu sambil menunggu ada yang menanyakan", s:3},{t:"Membaginya rata dengan panitia lain sebagai 'uang lelah'", s:2},{t:"Mengambilnya untuk keperluan pribadi karena tidak ada yang tahu", s:1}], ex:"Integritas keuangan menuntut transparansi penuh; dana sisa yang tidak dilaporkan sama dengan penggelapan."},
{id:"TKP-2212", q:"Rekan sekantor mengajak Anda ikut seminar yang ternyata berisi ceramah kebencian terhadap pemerintah yang sah dan ajakan makar. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak ikut, menjelaskan bahaya paham tersebut, dan melaporkan kegiatan itu ke pihak berwenang", s:5},{t:"Menolak ajakan dan tidak menghadiri seminar tersebut", s:4},{t:"Ikut hadir tetapi hanya duduk diam di belakang", s:3},{t:"Ikut hadir untuk mengambil materi lalu membagikannya ke teman", s:2},{t:"Ikut aktif dan mengajak rekan lain bergabung", s:1}], ex:"ASN dilarang terlibat kegiatan makar/radikal; menolak plus melapor adalah wujud nasionalisme dan integritas."},
{id:"TKP-2213", q:"Seorang calo menawarkan jasa 'memuluskan' kenaikan pangkat Anda dengan imbalan sejumlah uang. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan calo tersebut ke atasan/BKPSDM/inspektorat", s:5},{t:"Menolak tawaran dan menempuh kenaikan pangkat sesuai prosedur", s:4},{t:"Mengabaikan tawaran tanpa berbuat apa-apa", s:3},{t:"Menolak tetapi meminta calo mencarikan 'jalan lain' yang lebih murah", s:2},{t:"Menerima tawaran demi karier yang lebih cepat", s:1}], ex:"Kenaikan pangkat berbasis prestasi, bukan suap; melaporkan calo melindungi integritas sistem kepegawaian."},
{id:"TKP-2214", q:"Anda melihat bendahara pengeluaran, Dewi, memalsukan kuitansi perjalanan dinas. Sikap yang paling tepat adalah ....", opts:[{t:"Mengumpulkan bukti dan melaporkannya melalui WBS/inspektorat", s:5},{t:"Menegur Dewi dan memintanya mengembalikan selisih dana", s:4},{t:"Berpura-pura tidak tahu karena dia senior Anda", s:3},{t:"Meminta Dewi membagi keuntungannya agar Anda tutup mulut", s:2},{t:"Ikut meminta dibuatkan kuitansi palsu untuk perjalanan Anda", s:1}], ex:"Pemalsuan dokumen keuangan adalah korupsi; whistleblowing adalah jalur resmi dan terlindungi bagi pelapor."},
{id:"TKP-2215", q:"Saat jam kerja, beberapa rekan mengajak Anda nongkrong di warung kopi berjam-jam meninggalkan pelayanan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak ajakan, tetap melayani warga, dan mengingatkan rekan tentang disiplin jam kerja", s:5},{t:"Menolak ajakan dan tetap berada di meja pelayanan", s:4},{t:"Ikut sebentar lalu kembali sebelum ketahuan", s:3},{t:"Menolak ikut tetapi menutupi ketidakhadiran mereka bila ditanya", s:2},{t:"Ikut nongkrong karena semua orang melakukannya", s:1}], ex:"Disiplin jam kerja adalah kewajiban ASN; pelayanan publik tidak boleh dikorbankan demi bersantai."},
{id:"TKP-2216", q:"Kontraktor pemenang tender memberi Anda tiket liburan ke luar negeri sebagai 'apresiasi'. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak tegas dan melaporkannya sebagai gratifikasi ke atasan/UPG", s:5},{t:"Menolak pemberian tersebut dengan sopan", s:4},{t:"Menerima tiket tetapi tidak menggunakannya", s:3},{t:"Menerima tiket lalu memberikannya kepada keluarga", s:2},{t:"Menerima dan menggunakannya karena merasa sudah bekerja keras", s:1}], ex:"Gratifikasi dari pihak berkepentingan proyek wajib ditolak dan dilaporkan ke Unit Pengendalian Gratifikasi."},
{id:"TKP-2217", q:"Di media sosial, akun anonim menyebarkan hoaks bahwa pemerintah akan menghapus tunjangan ASN. Banyak rekan mempercayainya. Sikap yang paling tepat adalah ....", opts:[{t:"Tidak ikut menyebar, memverifikasi ke sumber resmi, dan mengedukasi rekan agar tidak termakan hoaks", s:5},{t:"Tidak ikut menyebarkan dan mengecek kebenarannya sendiri", s:4},{t:"Diam saja karena malas berdebat dengan rekan", s:3},{t:"Ikut membagikan agar rekan waspada, walau belum pasti benar", s:2},{t:"Ikut menyebar sambil menambahkan komentar provokatif", s:1}], ex:"ASN harus menjadi penangkal hoaks; memverifikasi dan mengedukasi adalah wujud profesionalisme di ruang digital."},
{id:"TKP-2218", q:"Atasan meminta Anda menandatangani berita acara serah terima barang yang belum pernah Anda periksa. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menandatangani sebelum memeriksa barang secara fisik sesuai prosedur", s:5},{t:"Menunda tanda tangan sampai ada kesempatan memeriksa", s:4},{t:"Menandatangani karena percaya pada atasan", s:3},{t:"Menandatangani tetapi mencatat keberatan secara lisan saja", s:2},{t:"Menandatangani tanpa memeriksa demi menyenangkan atasan", s:1}], ex:"Tanda tangan ASN adalah pertanggungjawaban hukum; menandatangani tanpa verifikasi membuka celah korupsi."},
{id:"TKP-2219", q:"Rekan Anda, Joko, terang-terangan menolak melayani warga dari suku tertentu dengan alasan keyakinannya. Sikap yang paling tepat adalah ....", opts:[{t:"Menegur Joko, melayani warga tersebut dengan baik, dan melaporkan perilaku diskriminatif itu", s:5},{t:"Menegur Joko dan mengambil alih pelayanan kepada warga tersebut", s:4},{t:"Membiarkan karena menghormati keyakinan rekan", s:3},{t:"Ikut menghindari warga tersebut agar tidak ribut dengan Joko", s:2},{t:"Mendukung Joko karena sependapat dengannya", s:1}], ex:"Pelayanan publik wajib tanpa diskriminasi; paham intoleran di lingkungan ASN harus ditegur dan dilaporkan."},
{id:"TKP-2220", q:"Anda ditawari menjadi 'tim sukses' calon kepala daerah dengan imbalan jabatan strategis bila menang. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak tegas dan melaporkan tawaran politisasi ASN tersebut", s:5},{t:"Menolak dan menjaga netralitas selama proses pemilu", s:4},{t:"Tidak menjawab dan berharap tawarannya dilupakan", s:3},{t:"Menolak jabatan tetapi diam-diam memberi dukungan moral", s:2},{t:"Menerima karena peluang kariernya besar", s:1}], ex:"Netralitas ASN mutlak; menjadi tim sukses adalah pelanggaran berat yang bisa berujung sanksi disiplin."},
{id:"TKP-2221", q:"Dalam rapat anggaran, diusulkan mark-up harga pengadaan alat tulis hingga tiga kali lipat untuk 'dana cadangan'. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak usulan mark-up, menyampaikan keberatan resmi, dan melaporkannya bila dipaksakan", s:5},{t:"Menolak menyetujui usulan mark-up tersebut", s:4},{t:"Diam dalam rapat agar tidak dimusuhi peserta lain", s:3},{t:"Setuju asalkan namanya tidak tercantum dalam dokumen", s:2},{t:"Mendukung usulan karena menguntungkan semua pihak", s:1}], ex:"Mark-up anggaran adalah korupsi; ASN berintegritas menolak dan berani menyampaikan keberatan resmi."},
{id:"TKP-2222", q:"Seorang warga memotret Anda saat menolak suapnya lalu mengancam menyebarkan foto dengan narasi fitnah. Sikap yang paling tepat adalah ....", opts:[{t:"Tetap menolak suap, menjelaskan prosedur resmi, dan melaporkan ancaman tersebut ke atasan/keamanan", s:5},{t:"Tetap menolak dan tidak terpengaruh ancaman", s:4},{t:"Ragu-ragu dan meminta waktu berpikir", s:3},{t:"Menerima suap agar foto tidak disebar", s:2},{t:"Menyerahkan uang pribadi agar warga menghapus foto", s:1}], ex:"Ancaman tidak boleh menggoyahkan integritas; tetap pada prosedur dan laporkan intimidasi melalui jalur resmi."},
{id:"TKP-2223", q:"Anda mengetahui rekan satu tim, Maya, memalsukan tanda tangan pimpinan pada surat tugas agar bisa dinas luar kota. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan pemalsuan tersebut ke atasan/inspektorat dengan bukti", s:5},{t:"Menegur Maya dan memintanya mengaku ke pimpinan", s:4},{t:"Berpura-pura tidak tahu karena tidak merugikan Anda", s:3},{t:"Meminta Maya membuatkan surat tugas palsu juga untuk Anda", s:2},{t:"Ikut menutupi karena dia teman dekat Anda", s:1}], ex:"Pemalsuan tanda tangan adalah tindak pidana; menutupi berarti ikut terlibat dalam pelanggaran hukum."},
{id:"TKP-2224", q:"Kelompok kecil di kantor Anda rutin mengadakan kajian yang mengajarkan bahwa ASN tidak boleh taat pada pimpinan non-muslim. Sikap yang paling tepat adalah ....", opts:[{t:"Tidak ikut, menjelaskan bahwa ketaatan pada aturan negara wajib, dan melaporkan kajian menyimpang tersebut", s:5},{t:"Tidak ikut serta dalam kajian tersebut", s:4},{t:"Diam saja karena takut dicap tidak saleh", s:3},{t:"Ikut sesekali agar tidak dikucilkan", s:2},{t:"Ikut aktif dan menyebarkan ajarannya", s:1}], ex:"Paham yang menolak ketaatan pada negara adalah benih radikalisme; ASN wajib setia pada Pancasila dan melaporkannya."},
{id:"TKP-2225", q:"Bendahara menyarankan agar honor kegiatan dibagi 'di bawah tangan' tanpa potong pajak agar lebih besar. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan meminta pembayaran honor sesuai ketentuan perpajakan resmi", s:5},{t:"Menolak menerima honor bila tidak sesuai aturan", s:4},{t:"Menerima saja karena semua panitia juga menerima", s:3},{t:"Menerima tetapi tidak ikut menyarankan ke orang lain", s:2},{t:"Setuju dan ikut menyarankan ke panitia lain", s:1}], ex:"Kepatuhan pajak adalah kewajiban; skema di bawah tangan merugikan negara dan melanggar integritas ASN."},
{id:"TKP-2226", q:"Atasan Anda meminta data pribadi warga (NIK dan KK) untuk kepentingan kampanye kerabatnya. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak memberikan data, menjelaskan perlindungan data pribadi, dan melaporkan permintaan tersebut", s:5},{t:"Menolak memberikan data warga tersebut", s:4},{t:"Berpura-pura data sedang tidak bisa diakses", s:3},{t:"Memberikan sebagian data yang dianggap tidak sensitif", s:2},{t:"Memberikan data karena perintah atasan", s:1}], ex:"Data pribadi warga dilindungi UU PDP; memberikannya untuk kampanye melanggar hukum dan netralitas ASN."},
{id:"TKP-2227", q:"Anda melihat spanduk bernada provokatif anti-pemerintah dipasang rekan di area parkir kantor. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan pemasangan tersebut ke pimpinan/keamanan dan meminta penertiban", s:5},{t:"Menegur rekan yang memasang agar mencopotnya", s:4},{t:"Mengabaikannya karena di area parkir, bukan ruang kerja", s:3},{t:"Membiarkannya karena setuju dengan isinya", s:2},{t:"Ikut membantu memasang spanduk serupa", s:1}], ex:"Fasilitas negara tidak boleh dipakai propaganda; ASN menjaga netralitas dan ketertiban lingkungan kerja."},
{id:"TKP-2228", q:"Seorang pengusaha katering menawarkan komisi 10% bila Anda memenangkan perusahaannya dalam tender konsumsi rapat. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan tawaran komisi ke panitia pengadaan/inspektorat", s:5},{t:"Menolak tawaran dan tetap menilai tender secara objektif", s:4},{t:"Tidak menanggapi tawaran tersebut", s:3},{t:"Menolak komisi tetapi tetap memenangkan perusahaannya", s:2},{t:"Menerima tawaran karena tender toh harus dimenangkan seseorang", s:1}], ex:"Komisi tender adalah suap; proses pengadaan harus objektif dan bebas konflik kepentingan."},
{id:"TKP-2229", q:"Rekan kerja Anda, Dedi, ketahuan mengambil ATK kantor dalam jumlah besar untuk dijual. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan pencurian aset negara tersebut ke atasan/inspektorat", s:5},{t:"Menegur Dedi dan memintanya mengembalikan barang", s:4},{t:"Diam karena nilainya kecil menurut Anda", s:3},{t:"Meminta Dedi membagi hasil penjualannya", s:2},{t:"Ikut mengambil karena melihat peluang", s:1}], ex:"Aset negara sekecil apa pun wajib dijaga; mencuri dan membiarkan pencurian sama-sama melanggar integritas."},
{id:"TKP-2230", q:"Menjelang pilkada, kepala dinas menginstruksikan seluruh ASN hadir di acara deklarasi dukungan calon tertentu. Sikap yang paling tepat adalah ....", opts:[{t:"Tidak hadir, dan melaporkan instruksi yang melanggar netralitas itu ke Bawaslu/KASN", s:5},{t:"Tidak hadir dengan alasan tugas kedinasan", s:4},{t:"Hadir tetapi hanya duduk di belakang tanpa atribut", s:3},{t:"Hadir karena takut dinilai tidak loyal pada pimpinan", s:2},{t:"Hadir dengan atribut dukungan penuh", s:1}], ex:"Instruksi mobilisasi politik melanggar netralitas ASN; menolak dan melapor ke Bawaslu/KASN adalah langkah tepat."},
{id:"TKP-2231", q:"Anda diminta menjadi saksi bahwa barang pengadaan sudah diterima, padahal barang belum datang. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menjadi saksi palsu dan meminta pemeriksaan dilakukan saat barang benar-benar tiba", s:5},{t:"Menolak menandatangani berita acara tersebut", s:4},{t:"Menunda dengan alasan sibuk", s:3},{t:"Menandatangani tetapi menulis catatan kecil keberatan", s:2},{t:"Menandatangani karena diminta rekan", s:1}], ex:"Kesaksian palsu dalam pengadaan adalah pemalsuan; integritas menuntut hanya menandatangani yang benar-benar diverifikasi."},
{id:"TKP-2232", q:"Di ruang istirahat, rekan Anda menyetel ceramah yang mengkafirkan sesama ASN berbeda mazhab. Sikap yang paling tepat adalah ....", opts:[{t:"Meminta dihentikan dengan santun, menjelaskan pentingnya toleransi, dan melaporkan bila berlanjut", s:5},{t:"Meminta rekan mengganti dengan tontonan lain", s:4},{t:"Keluar ruangan tanpa berkomentar", s:3},{t:"Mendengarkan saja sambil mengerjakan hal lain", s:2},{t:"Ikut menyimak dan menyetujuinya", s:1}], ex:"Ujaran takfir di lingkungan kerja adalah benih intoleransi; ASN wajib menjaga kerukunan dan menegakkan toleransi."},
{id:"TKP-2233", q:"Warga menawarkan Anda menjadi 'orang dalam' pengurusan sertifikat tanah dengan imbalan tiap berkas. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak tegas dan melaporkan tawaran percaloan tersebut ke atasan", s:5},{t:"Menolak dan menyarankan warga mengurus sendiri via loket resmi", s:4},{t:"Mengabaikan tawaran tanpa tindak lanjut", s:3},{t:"Menolak tetapi memberi tahu cara mempercepat lewat jalur tidak resmi", s:2},{t:"Menerima karena penghasilannya menggiurkan", s:1}], ex:"Percaloan layanan publik adalah pungli terselubung; menolak plus mengarahkan ke jalur resmi wujud profesionalisme."},
{id:"TKP-2234", q:"Laporan kinerja triwulan Anda diminta atasan untuk 'dipercantik' agar dinas mendapat penghargaan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak memanipulasi data dan menyajikan capaian sesuai fakta", s:5},{t:"Menyajikan data apa adanya tanpa melebih-lebihkan", s:4},{t:"Menyerahkan draf kosong agar atasan yang mengisi", s:3},{t:"Melebihkan sedikit agar terlihat bagus", s:2},{t:"Menuruti permintaan demi nama baik dinas", s:1}], ex:"Manipulasi data kinerja merusak akuntabilitas; profesionalisme menuntut laporan berbasis bukti yang jujur."},
{id:"TKP-2235", q:"Anda menemukan akun media sosial rekan ASN yang aktif menyebarkan propaganda kelompok teroris. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan akun tersebut ke pimpinan dan aparat penegak hukum/BNPT", s:5},{t:"Mengingatkan rekan agar berhenti menyebarkannya", s:4},{t:"Berhenti mengikuti akunnya tanpa berbuat apa-apa", s:3},{t:"Menyukai postingannya agar tidak dicurigai", s:2},{t:"Ikut menyebarkan karena penasaran", s:1}], ex:"Propaganda terorisme adalah ancaman negara; ASN wajib melaporkannya ke aparat, bukan sekadar unfollow."},
{id:"TKP-2236", q:"Panitia pengadaan meminta Anda merahasiakan kebocoran harga penawaran kepada peserta tertentu. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan kebocoran informasi tender ke APIP/inspektorat", s:5},{t:"Menolak terlibat dalam kebocoran tersebut", s:4},{t:"Diam dan tidak ikut campur urusan panitia", s:3},{t:"Memanfaatkan info bocoran untuk kerabat yang ikut tender", s:2},{t:"Ikut membocorkan demi imbalan", s:1}], ex:"Kerahasiaan tender melindungi persaingan sehat; membocorkannya adalah kolusi yang merusak integritas pengadaan."},
{id:"TKP-2237", q:"Atasan Anda sering menggunakan mobil dinas untuk keperluan keluarga di akhir pekan. Sikap yang paling tepat adalah ....", opts:[{t:"Menyampaikan keberatan secara santun dan melaporkan penyalahgunaan aset negara bila berlanjut", s:5},{t:"Mengingatkan atasan bahwa mobil dinas hanya untuk keperluan dinas", s:4},{t:"Tidak peduli karena bukan wewenang Anda", s:3},{t:"Meminta izin ikut memakai mobil dinas untuk keperluan pribadi", s:2},{t:"Ikut menggunakan kendaraan dinas untuk urusan pribadi", s:1}], ex:"Aset negara hanya untuk kepentingan dinas; penyalahgunaannya wajib diingatkan dan dilaporkan."},
{id:"TKP-2238", q:"Seorang tokoh ormas menekan Anda agar menolak izin kegiatan ibadah kelompok minoritas di wilayah Anda. Sikap yang paling tepat adalah ....", opts:[{t:"Tetap memproses izin sesuai aturan, menjelaskan kebebasan beribadah, dan melaporkan tekanan tersebut", s:5},{t:"Tetap memproses izin sesuai prosedur yang berlaku", s:4},{t:"Menunda-nunda proses izin agar tidak diprotes ormas", s:3},{t:"Menolak izin demi menghindari konflik", s:2},{t:"Menolak izin dan ikut berorasi bersama ormas", s:1}], ex:"Kebebasan beribadah dijamin konstitusi; ASN tidak boleh tunduk pada tekanan intoleran dalam pelayanan."},
{id:"TKP-2239", q:"Rekan Anda, Nur, meminta password aplikasi kepegawaian Anda agar bisa 'membantu' mengisi laporan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan menjelaskan bahwa kredensial bersifat pribadi serta tidak boleh dibagikan", s:5},{t:"Menolak memberikannya dengan sopan", s:4},{t:"Memberikan tetapi memintanya segera diganti", s:3},{t:"Memberikan karena percaya padanya", s:2},{t:"Memberikan dan memintanya mengisikan laporan Anda juga", s:1}], ex:"Kredensial sistem adalah tanggung jawab pribadi; membagikannya melanggar keamanan informasi dan disiplin ASN."},
{id:"TKP-2240", q:"Dalam perjalanan dinas, Anda diberi uang saku lebih karena kuitansi hotel 'disesuaikan' panitia. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak selisihnya dan melaporkan praktik penyesuaian kuitansi tersebut", s:5},{t:"Mengembalikan kelebihan uang saku ke bendahara", s:4},{t:"Menyimpan kelebihan sebagai tabungan diam-diam", s:3},{t:"Menggunakannya untuk mentraktir rekan perjalanan", s:2},{t:"Menggunakannya untuk keperluan pribadi", s:1}], ex:"Penyesuaian kuitansi adalah pemalsuan; kelebihan dana dinas wajib dikembalikan, bukan dinikmati."},
{id:"TKP-2241", q:"Calon peserta seleksi CPNS menawarkan Anda uang agar diloloskan. Padahal Anda hanya staf administrasi. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak tegas dan melaporkan upaya suap seleksi tersebut ke panitia/BKN", s:5},{t:"Menolak dan menjelaskan seleksi berjalan transparan via sistem", s:4},{t:"Mengabaikan tawaran tersebut", s:3},{t:"Menolak uang tetapi berjanji 'membantu sebisanya'", s:2},{t:"Menerima dan berjanji mengusahakan", s:1}], ex:"Suap seleksi CPNS merusak meritokrasi; menolak plus melapor melindungi integritas rekrutmen ASN."},
{id:"TKP-2242", q:"Anda melihat rekan memasang stiker simbol organisasi terlarang di laptop dinasnya. Sikap yang paling tepat adalah ....", opts:[{t:"Menegur rekan dan melaporkan simbol organisasi terlarang itu ke pimpinan/keamanan", s:5},{t:"Memintanya mencopot stiker tersebut", s:4},{t:"Berpura-pura tidak melihat", s:3},{t:"Membiarkannya karena urusan pribadi", s:2},{t:"Ikut memasang simbol serupa", s:1}], ex:"Simbol organisasi terlarang di fasilitas negara adalah pelanggaran serius; wajib ditegur dan dilaporkan."},
{id:"TKP-2243", q:"Kepala sekolah meminta Anda mengubah nilai rapor anak pejabat agar bisa masuk sekolah favorit. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak mengubah nilai dan melaporkannya bila ada tekanan lanjutan", s:5},{t:"Menolak dan tetap mencatat nilai sesuai kemampuan siswa", s:4},{t:"Menyerahkan ke wali kelas lain agar bukan Anda yang memutuskan", s:3},{t:"Mengubah sedikit agar tidak terlalu mencolok", s:2},{t:"Mengubah nilai demi menjaga hubungan dengan pejabat", s:1}], ex:"Integritas pendidikan menuntut penilaian objektif; mengubah nilai adalah pemalsuan dokumen akademik."},
{id:"TKP-2244", q:"Atasan meminta Anda menghapus arsip digital pengadaan tahun lalu sebelum diaudit. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menghapus arsip dan melaporkan perintah tersebut ke APIP/inspektorat", s:5},{t:"Menolak menghapus karena arsip wajib disimpan sesuai jadwal retensi", s:4},{t:"Berpura-pura lupa password arsip", s:3},{t:"Menghapus sebagian arsip yang dianggap sensitif", s:2},{t:"Menghapus seluruh arsip sesuai perintah", s:1}], ex:"Penghapusan arsip untuk menghindari audit adalah obstruction; arsip negara wajib dijaga sesuai ketentuan."},
{id:"TKP-2245", q:"Seorang penceramah di acara kantor menyampaikan bahwa demokrasi itu haram dan harus diganti. Sikap yang paling tepat adalah ....", opts:[{t:"Tidak mengikuti ajakannya, dan melaporkan materi menyimpang itu ke pimpinan", s:5},{t:"Keluar dari acara dan tidak mengikuti ajarannya", s:4},{t:"Tetap duduk diam sampai acara selesai", s:3},{t:"Merekam ceramah untuk disebar ke grup", s:2},{t:"Ikut menyetujui dan menyebarkannya", s:1}], ex:"Menolak ideologi anti-demokrasi dan melaporkannya adalah wujud nasionalisme ASN yang setia pada Pancasila."},
{id:"TKP-2246", q:"Anda diminta rekan untuk menjadi 'penjamin' pinjaman online miliknya memakai nama instansi. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak tegas karena mencatut nama instansi melanggar kode etik dan berisiko hukum", s:5},{t:"Menolak dengan alasan pribadi", s:4},{t:"Menunda jawaban sampai dia lupa", s:3},{t:"Setuju asalkan tidak ada dokumen resmi", s:2},{t:"Setuju demi membantu teman", s:1}], ex:"Mencatut nama instansi untuk kepentingan pribadi dilarang kode etik; penolakan tegas melindungi nama baik lembaga."},
{id:"TKP-2247", q:"Warga miskin meminta surat keterangan tidak mampu, tetapi kuota bantuan sudah habis dan petugas menyarankan 'memberi sedikit' agar dibantu. Sikap yang paling tepat adalah ....", opts:[{t:"Memproses sesuai antrean resmi, menolak pungli, dan melaporkan oknum yang meminta imbalan", s:5},{t:"Membantu mengurus sesuai prosedur tanpa meminta imbalan", s:4},{t:"Menyarankan warga datang lagi bulan depan", s:3},{t:"Meminta warga memberi imbalan kecil agar diprioritaskan", s:2},{t:"Ikut meminta imbalan dari warga tersebut", s:1}], ex:"Warga miskin justru paling wajib dilindungi dari pungli; melapor memberantas praktik pemerasan."},
{id:"TKP-2248", q:"Anda menerima pesan berantai ajakan boikot produk milik kelompok etnis tertentu disertai ujaran kebencian. Sikap yang paling tepat adalah ....", opts:[{t:"Tidak meneruskan, menghapus, dan mengedukasi pengirim tentang bahaya ujaran kebencian", s:5},{t:"Tidak meneruskan pesan tersebut", s:4},{t:"Membiarkannya menumpuk di ponsel", s:3},{t:"Meneruskan ke beberapa teman dekat saja", s:2},{t:"Meneruskan ke semua grup agar viral", s:1}], ex:"ASN menjadi teladan di ruang digital; memutus rantai ujaran kebencian plus edukasi cegah intoleransi meluas."},
{id:"TKP-2249", q:"Atasan Anda memerintahkan perjalanan dinas fiktif — namanya dicantumkan padahal tidak berangkat — agar dapat uang saku. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak namanya dicantumkan dan melaporkan praktik perjalanan fiktif tersebut", s:5},{t:"Menolak ikut serta dalam perjalanan fiktif", s:4},{t:"Diam dan membiarkan namanya dicantumkan", s:3},{t:"Menolak ikut tetapi tidak melapor", s:2},{t:"Ikut serta karena lumayan dapat uang saku", s:1}], ex:"Perjalanan dinas fiktif adalah korupsi klasik; menolak dan melapor adalah wujud integritas dan disiplin anggaran."},
{id:"TKP-2250", q:"Seorang rekan mengajak Anda menandatangani petisi penolakan terhadap ASN berbeda agama menjadi pimpinan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menandatangani, menjelaskan meritokrasi, dan melaporkan bila petisi disebar di lingkungan kerja", s:5},{t:"Menolak menandatangani petisi tersebut", s:4},{t:"Tidak menanggapi ajakan tersebut", s:3},{t:"Menandatangani agar tidak dimusuhi", s:2},{t:"Ikut menggalang tanda tangan", s:1}], ex:"Jabatan ASN berbasis kompetensi, bukan SARA; petisi diskriminatif bertentangan dengan meritokrasi dan toleransi."},
{id:"TKP-2251", q:"Anda bertugas di imigrasi. Seorang agen menawarkan fee tiap paspor yang Anda terbitkan lewat jalur cepat tanpa verifikasi. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan agen tersebut ke atasan/inspektorat", s:5},{t:"Menolak tawaran dan tetap menerbitkan paspor sesuai prosedur", s:4},{t:"Mengabaikan tawaran tanpa tindak lanjut", s:3},{t:"Menolak fee tetapi tetap memproses via jalur cepat", s:2},{t:"Menerima tawaran karena prosedurnya merepotkan", s:1}], ex:"Jalur cepat tanpa verifikasi membahayakan keamanan negara; menolak plus melapor adalah integritas petugas imigrasi."},
{id:"TKP-2252", q:"Rekan Anda, Putri, ketahuan mengunggah foto dokumen rahasia dinas ke status media sosialnya. Sikap yang paling tepat adalah ....", opts:[{t:"Memintanya segera menghapus dan melaporkan kebocoran dokumen ke pimpinan/keamanan informasi", s:5},{t:"Menegur Putri agar menghapus unggahan tersebut", s:4},{t:"Berpura-pura tidak melihat unggahannya", s:3},{t:"Menyimpan tangkapan layar untuk bahan gosip", s:2},{t:"Ikut menyebarkan karena isinya menarik", s:1}], ex:"Dokumen rahasia dinas dilindungi UU; kebocorannya wajib dilaporkan, bukan disebarluaskan."},
{id:"TKP-2253", q:"Saat apel pagi, Anda melihat beberapa ASN berseragam lengkap tetapi langsung pulang setelah absen. Sikap yang paling tepat adalah ....", opts:[{t:"Tetap mengikuti apel penuh dan melaporkan praktik absen-pulang ke pimpinan", s:5},{t:"Tetap mengikuti apel sampai selesai sesuai kewajiban", s:4},{t:"Ikut absen lalu pulang seperti mereka", s:3},{t:"Tetap di kantor tetapi tidak mengerjakan apa-apa", s:2},{t:"Ikut pulang karena merasa rugi bila sendirian", s:1}], ex:"Disiplin apel adalah kewajiban; melaporkan praktik mangkir menunjukkan tanggung jawab, bukan ikut-ikutan."},
{id:"TKP-2254", q:"Seorang ustaz di pengajian kantor mengajarkan bahwa ASN wajib menolak membayar pajak karena pemerintah zalim. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak ajaran tersebut, menjelaskan kewajiban pajak, dan melaporkan materi menyimpang itu", s:5},{t:"Tidak mengikuti ajarannya dan tetap taat membayar pajak", s:4},{t:"Diam dan keluar ruangan pelan-pelan", s:3},{t:"Ikut hadir rutin agar dianggap saleh", s:2},{t:"Ikut menyebarkan ajaran tersebut", s:1}], ex:"Menolak pajak dengan dalih agama adalah paham menyimpang; ASN wajib taat hukum dan melapor."},
{id:"TKP-2255", q:"Panitia lelang meminta Anda mengubah spesifikasi teknis agar hanya satu perusahaan yang memenuhi syarat. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak mengubah spesifikasi dan melaporkan pengaturan lelang tersebut", s:5},{t:"Menolak dan mempertahankan spesifikasi objektif", s:4},{t:"Menyerahkan sepenuhnya pada keputusan panitia", s:3},{t:"Mengubah sedikit agar tidak terlalu kentara", s:2},{t:"Menuruti karena diperintah panitia", s:1}], ex:"Pengaturan spesifikasi untuk pemenang tertentu adalah kolusi; spesifikasi harus objektif dan terbuka."},
{id:"TKP-2256", q:"Atasan Anda, Bu Dewi, meminta Anda memprioritaskan pengurusan izin usaha milik suaminya. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak perlakuan khusus, memproses sesuai antrean, dan mencatat konflik kepentingan tersebut", s:5},{t:"Menolak dan tetap memproses sesuai urutan", s:4},{t:"Memprosesnya seperti biasa tanpa komentar", s:3},{t:"Mempercepat sedikit agar atasan senang", s:2},{t:"Mendahulukan izin suami atasan", s:1}], ex:"Konflik kepentingan atasan tidak boleh dipenuhi; pelayanan harus adil tanpa memandang relasi."},
{id:"TKP-2257", q:"Anda menemukan grup chat rekan sekantor yang khusus menghina pemerintah dan merencanakan aksi menolak tugas negara. Sikap yang paling tepat adalah ....", opts:[{t:"Keluar dari grup dan melaporkannya ke pimpinan/aparat", s:5},{t:"Keluar dari grup dan tidak terlibat", s:4},{t:"Tetap di grup tetapi tidak berkomentar", s:3},{t:"Tetap di grup untuk memantau diam-diam", s:2},{t:"Ikut aktif merencanakan aksi", s:1}], ex:"Perencanaan penolakan tugas negara adalah pembangkangan; ASN wajib melapor, bukan jadi penonton."},
{id:"TKP-2258", q:"Seorang wajib pajak menawarkan Anda 'uang jasa' agar tunggakan pajaknya dihapus dari sistem. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak tegas dan melaporkan upaya suap ke atasan/inspektorat", s:5},{t:"Menolak dan menjelaskan tunggakan wajib dibayar sesuai ketentuan", s:4},{t:"Berpura-pura tidak mendengar", s:3},{t:"Menolak uang tetapi memberi tahu cara menghindari penagihan", s:2},{t:"Menerima dan menghapus tunggakan dari sistem", s:1}], ex:"Menghapus tunggakan pajak demi suap merugikan negara triliunan; penolakan dan pelaporan adalah integritas fiskus."},
{id:"TKP-2259", q:"Rekan Anda, Slamet, selalu pulang tepat waktu tetapi pekerjaannya menumpuk dan dilimpahkan ke Anda. Sikap yang paling tepat adalah ....", opts:[{t:"Berdiskusi dengan Slamet tentang pembagian kerja yang adil dan melaporkannya bila tidak berubah", s:5},{t:"Menegur Slamet dan memintanya menyelesaikan pekerjaannya sendiri", s:4},{t:"Mengerjakan saja tanpa protes", s:3},{t:"Ikut menumpuk pekerjaan agar sama-sama santai", s:2},{t:"Melimpahkan balik pekerjaan Anda ke rekan lain", s:1}], ex:"Profesionalisme menuntut pembagian kerja adil; komunikasi terbuka dulu, eskalasi bila tak berubah."},
{id:"TKP-2260", q:"Anda diminta menjadi narasumber acara yang ternyata disponsori ormas berideologi ekstrem. Sikap yang paling tepat adalah ....", opts:[{t:"Membatalkan kehadiran setelah tahu sponsornya dan melaporkan ke pimpinan", s:5},{t:"Membatalkan kehadiran sebagai narasumber", s:4},{t:"Tetap hadir tetapi tidak membahas ideologi", s:3},{t:"Tetap hadir karena sudah terlanjur janji", s:2},{t:"Hadir dan memuji ormas tersebut", s:1}], ex:"ASN dilarang memberi legitimasi pada ormas ekstrem; membatalkan plus melapor menjaga netralitas dan nasionalisme."},
{id:"TKP-2261", q:"Bendahara meminta Anda menandatangani kuitansi kosong untuk 'mempermudah' pencairan dana kegiatan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menandatangani dokumen kosong dan melaporkan praktik tersebut", s:5},{t:"Menolak menandatangani kuitansi kosong", s:4},{t:"Menunda tanda tangan dengan berbagai alasan", s:3},{t:"Menandatangani satu lembar saja", s:2},{t:"Menandatangani karena percaya bendahara", s:1}], ex:"Dokumen kosong yang ditandatangani adalah cek kosong korupsi; integritas menuntut verifikasi sebelum tanda tangan."},
{id:"TKP-2262", q:"Saat pilkada, tim sukses meminta data penerima bansos di wilayah Anda untuk dibagi-bagi saat kampanye. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak memberikan data dan melaporkan politisasi bansos ke Bawaslu", s:5},{t:"Menolak memberikan data penerima bansos", s:4},{t:"Berpura-pura data belum direkap", s:3},{t:"Memberikan data yang sudah usang saja", s:2},{t:"Memberikan data demi imbalan", s:1}], ex:"Bansos bukan alat kampanye; memberikan datanya melanggar netralitas ASN dan perlindungan data."},
{id:"TKP-2263", q:"Anda melihat petugas parkir liar memungut retribusi di area kantor tanpa karcis resmi. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan pungli parkir tersebut ke pimpinan/dinas terkait", s:5},{t:"Menegur petugas dan memintanya menunjukkan dasar pungutan", s:4},{t:"Membayar saja agar tidak ribet", s:3},{t:"Membayar sambil mengeluh di media sosial", s:2},{t:"Ikut menjadi tukang parkir liar saat jam istirahat", s:1}], ex:"Pungutan tanpa dasar resmi adalah pungli; ASN tidak boleh menormalisasinya dengan membayar diam-diam."},
{id:"TKP-2264", q:"Rekan Anda, Fajar, mengajak Anda ikut latihan bela diri yang ternyata wadah rekrutmen kelompok radikal. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak ikut, dan melaporkan indikasi rekrutmen radikal tersebut ke aparat", s:5},{t:"Menolak ajakan dan menjauhi kegiatan itu", s:4},{t:"Ikut sekali untuk melihat-lihat", s:3},{t:"Ikut karena butuh teman latihan", s:2},{t:"Ikut aktif dan mengajak rekan lain", s:1}], ex:"Rekrutmen radikal berkedok kegiatan positif wajib diwaspadai; menolak plus melapor melindungi lingkungan kerja."},
{id:"TKP-2265", q:"Atasan menyuruh Anda membuat laporan pertanggungjawaban kegiatan yang tidak pernah dilaksanakan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak membuat LPJ fiktif dan melaporkan perintah tersebut", s:5},{t:"Menolak membuat laporan fiktif", s:4},{t:"Membuat draf tetapi tidak menandatangani", s:3},{t:"Membuat LPJ dengan nominal kecil saja", s:2},{t:"Membuat LPJ sesuai perintah", s:1}], ex:"LPJ fiktif adalah korupsi anggaran; ASN wajib menolak dokumen palsu apa pun bentuknya."},
{id:"TKP-2266", q:"Seorang pengembang perumahan meminta Anda meloloskan IMB di zona hijau dengan imbalan satu unit rumah. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan tawaran suap perizinan tersebut", s:5},{t:"Menolak dan menjelaskan aturan zonasi yang berlaku", s:4},{t:"Tidak menanggapi tawaran itu", s:3},{t:"Menolak rumah tetapi memberi tahu cara memutar aturan", s:2},{t:"Menerima dan meloloskan IMB", s:1}], ex:"Suap perizinan merusak tata ruang dan hukum; penolakan tegas plus pelaporan wujud integritas."},
{id:"TKP-2267", q:"Anda mengetahui rekan ASN aktif menjadi admin grup yang menyebarkan ujaran kebencian antarumat beragama. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan aktivitas tersebut ke pimpinan dan aparat penegak hukum", s:5},{t:"Menasihati rekan agar berhenti menjadi admin grup itu", s:4},{t:"Keluar dari grup tanpa berbuat apa-apa", s:3},{t:"Tetap di grup agar tidak dicurigai", s:2},{t:"Ikut membantu menyebarkan kontennya", s:1}], ex:"Admin grup ujaran kebencian oleh ASN adalah pelanggaran berat; wajib dilaporkan ke pimpinan dan aparat."},
{id:"TKP-2268", q:"Saat verifikasi berkas CPNS, Anda menemukan ijazah palsu milik kerabat atasan. Atasan meminta Anda meloloskannya. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak meloloskan dan melaporkan temuan ijazah palsu sesuai prosedur", s:5},{t:"Menolak dan menggugurkan berkas yang tidak valid", s:4},{t:"Mengembalikan berkas tanpa keterangan", s:3},{t:"Meloloskan tetapi mencatat sebagai 'perhatian khusus'", s:2},{t:"Meloloskan demi atasan", s:1}], ex:"Ijazah palsu adalah pemalsuan dokumen; meloloskannya merusak meritokrasi dan melanggar hukum."},
{id:"TKP-2269", q:"Dana operasional kantor Anda gunakan untuk mentraktir keluarga saat acara pribadi. Sikap yang paling tepat adalah ....", opts:[{t:"Tidak menggunakan dana kantor untuk kepentingan pribadi dan mengganti bila terlanjur terpakai", s:5},{t:"Menghindari penggunaan dana kantor untuk urusan pribadi", s:4},{t:"Menggunakannya sedikit karena merasa sudah lembur", s:3},{t:"Menggunakannya lalu menutupi dengan kuitansi lain", s:2},{t:"Menggunakannya karena merasa berhak", s:1}], ex:"Dana operasional hanya untuk kepentingan dinas; memakainya untuk pribadi adalah penyalahgunaan wewenang."},
{id:"TKP-2270", q:"Seorang caleg memasang baliho di pagar kantor Anda tanpa izin. Sikap yang paling tepat adalah ....", opts:[{t:"Meminta penurunan baliho dan melaporkan pelanggaran ke Bawaslu/Satpol PP", s:5},{t:"Meminta tim caleg mencopot baliho tersebut", s:4},{t:"Membiarkannya karena bukan urusan Anda", s:3},{t:"Membiarkannya karena Anda simpatisan caleg itu", s:2},{t:"Ikut membantu memasang baliho lain", s:1}], ex:"Fasilitas negara wajib netral dari atribut kampanye; ASN menegakkan netralitas di lingkungan kerjanya."},
{id:"TKP-2271", q:"Rekan Anda, Andi, menawarkan jasa 'mengurus' SK kenaikan pangkat rekan lain dengan tarif tertentu. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak terlibat dan melaporkan praktik percaloan tersebut", s:5},{t:"Menolak dan mengingatkan Andi bahwa itu pungli", s:4},{t:"Tidak ikut campur urusan Andi", s:3},{t:"Menggunakan jasanya sekali karena butuh cepat", s:2},{t:"Ikut menjadi makelar bersamanya", s:1}], ex:"Percaloan urusan kepegawaian adalah pungli; melaporkannya melindungi rekan dari pemerasan."},
{id:"TKP-2272", q:"Dalam diklat, instruktur mengajarkan bahwa loyalitas pada kelompok lebih utama daripada loyalitas pada negara. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak paham tersebut dan melaporkan materi menyimpang ke penyelenggara diklat", s:5},{t:"Tidak mengikuti ajaran dan tetap setia pada negara", s:4},{t:"Diam agar tidak dianggap pembangkang", s:3},{t:"Mencatat materinya untuk dibagikan", s:2},{t:"Menyetujui dan menyebarkannya", s:1}], ex:"Loyalitas ASN adalah pada Pancasila dan NKRI; paham yang menggesernya adalah radikalisme yang wajib dilaporkan."},
{id:"TKP-2273", q:"Anda diminta atasan menaikkan nilai evaluasi kinerja rekan yang malas agar terlihat kompak. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan menilai kinerja sesuai fakta yang terukur", s:5},{t:"Menilai sesuai kinerja sebenarnya", s:4},{t:"Memberi nilai tengah agar aman", s:3},{t:"Menaikkan sedikit sebagai toleransi", s:2},{t:"Menaikkan nilainya sesuai permintaan", s:1}], ex:"Penilaian kinerja harus objektif berbasis bukti; memanipulasinya merusak meritokrasi dan akuntabilitas."},
{id:"TKP-2274", q:"Seorang pasien di RSUD menawarkan Anda uang agar antrean operasinya dimajukan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan menjelaskan antrean berdasarkan skala kegawatan medis", s:5},{t:"Menolak dan tetap mengikuti urutan medis", s:4},{t:"Menerima uang tetapi tetap mengikuti antrean", s:3},{t:"Menolak uang tetapi menyelipkan antreannya", s:2},{t:"Menerima dan memajukan antreannya", s:1}], ex:"Antrean layanan kesehatan berbasis kegawatan, bukan uang; gratifikasi di RS melanggar etik pelayanan publik."},
{id:"TKP-2275", q:"Anda melihat dokumen tender difotokopi rekan untuk diberikan ke peserta tertentu. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan kebocoran dokumen tender ke panitia/APIP", s:5},{t:"Menegur rekan dan memintanya menghentikan", s:4},{t:"Berpura-pura tidak melihat", s:3},{t:"Meminta salinannya untuk kerabat Anda", s:2},{t:"Ikut membantu memfotokopi", s:1}], ex:"Kebocoran dokumen tender merusak persaingan sehat; melaporkannya menjaga integritas pengadaan."},
{id:"TKP-2276", q:"Atasan Anda meminta Anda menghadiri pengajian rutin yang materinya kerap menyudutkan pemerintah yang sah. Sikap yang paling tepat adalah ....", opts:[{t:"Tidak hadir dan melaporkan indikasi materi menyimpang tersebut", s:5},{t:"Tidak menghadiri pengajian tersebut", s:4},{t:"Hadir tetapi tidak menyimak", s:3},{t:"Hadir karena perintah atasan", s:2},{t:"Hadir aktif dan menyebarkan materinya", s:1}], ex:"Perintah atasan tidak membenarkan mengikuti kajian menyimpang; ASN wajib kritis dan melapor."},
{id:"TKP-2277", q:"Seorang supplier mengirim bingkisan mahal ke rumah Anda menjelang evaluasi kontrak. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak/mengembalikan bingkisan dan melaporkannya sebagai gratifikasi", s:5},{t:"Menolak bingkisan tersebut", s:4},{t:"Menerima tetapi tidak memengaruhi evaluasi", s:3},{t:"Menerima dan memberikannya ke orang lain", s:2},{t:"Menerima dan memenangkan supplier tersebut", s:1}], ex:"Bingkisan dari pihak berkontrak adalah gratifikasi; wajib ditolak dan dilaporkan ke UPG."},
{id:"TKP-2278", q:"Rekan Anda, Rina, ketahuan menyontek saat ujian dinas kenaikan pangkat. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan kecurangan tersebut ke pengawas/panitia ujian", s:5},{t:"Menegur Rina agar berhenti menyontek", s:4},{t:"Berpura-pura tidak melihat", s:3},{t:"Meminta contekan darinya", s:2},{t:"Ikut menyontek bersamanya", s:1}], ex:"Kecurangan ujian dinas merusak meritokrasi; melaporkannya menjaga keadilan bagi peserta jujur."},
{id:"TKP-2279", q:"Anda ditugasi mendata penerima bantuan, tetapi ketua RT meminta Anda memasukkan nama keluarganya yang mampu. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan mendata sesuai kriteria resmi hasil verifikasi lapangan", s:5},{t:"Menolak dan tetap berpegang pada data verifikasi", s:4},{t:"Mencatat tetapi menandainya untuk ditinjau nanti", s:3},{t:"Memasukkan satu nama agar tidak ribut", s:2},{t:"Menuruti agar hubungan dengan RT baik", s:1}], ex:"Data bantuan harus valid hasil verifikasi; tekanan pihak mana pun tidak boleh mengubahnya."},
{id:"TKP-2280", q:"Di kantor Anda beredar selebaran ajakan mendirikan negara berdasarkan paham kelompok tertentu. Sikap yang paling tepat adalah ....", opts:[{t:"Tidak ikut, mengumpulkan selebaran sebagai bukti, dan melaporkannya ke pimpinan/aparat", s:5},{t:"Tidak ikut serta dan mengabaikan selebaran itu", s:4},{t:"Membaca sekilas lalu membuangnya", s:3},{t:"Menyimpan untuk dibaca di rumah", s:2},{t:"Ikut menyebarkan ke rekan lain", s:1}], ex:"Ajakan mengganti ideologi negara adalah ancaman serius; mengamankan bukti dan melapor adalah kewajiban ASN."},
{id:"TKP-2281", q:"Atasan meminta Anda menggunakan stempel dinas untuk melegalkan surat pribadi miliknya. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak karena stempel dinas hanya untuk dokumen resmi kedinasan", s:5},{t:"Menolak dengan sopan", s:4},{t:"Menunda dengan alasan stempel sedang dipakai", s:3},{t:"Mengizinkan sekali saja", s:2},{t:"Mengizinkan demi atasan", s:1}], ex:"Stempel dinas adalah simbol kewenangan negara; penyalahgunaannya untuk urusan pribadi dilarang."},
{id:"TKP-2282", q:"Anda melihat kasir loket, Budi, tidak memberikan kembalian penuh kepada warga lansia. Sikap yang paling tepat adalah ....", opts:[{t:"Menegur Budi, memastikan kembalian dikembalikan, dan melaporkan bila berulang", s:5},{t:"Menegur Budi dan memintanya mengembalikan kembalian", s:4},{t:"Menganggapnya kekhilafan kecil", s:3},{t:"Membiarkannya karena bukan tugas Anda", s:2},{t:"Ikut mengambil selisih kembalian warga", s:1}], ex:"Memanfaatkan warga rentan adalah penggelapan; ASN wajib melindungi masyarakat dan menegakkan kejujuran."},
{id:"TKP-2283", q:"Seorang tokoh meminta Anda memfasilitasi izin keramaian untuk aksi yang menolak hasil pemilu yang sah. Sikap yang paling tepat adalah ....", opts:[{t:"Memproses sesuai aturan perizinan yang berlaku dan melaporkan bila ada indikasi makar", s:5},{t:"Memproses izin sesuai prosedur tanpa memihak", s:4},{t:"Menunda proses izin tanpa alasan jelas", s:3},{t:"Menolak izin karena tidak sependapat", s:2},{t:"Mempercepat izin karena mendukung aksinya", s:1}], ex:"Perizinan harus prosedural dan netral; ASN tidak boleh memihak aksi politik apa pun."},
{id:"TKP-2284", q:"Rekan Anda mengajak patungan 'dana keamanan' untuk oknum agar proyek kantor tidak diganggu. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak patungan dan melaporkan pemerasan tersebut ke aparat", s:5},{t:"Menolak ikut patungan", s:4},{t:"Ikut patungan kecil agar aman", s:3},{t:"Tidak ikut tetapi tidak melapor", s:2},{t:"Ikut patungan dan mengajak rekan lain", s:1}], ex:"Dana keamanan untuk oknum adalah pemerasan; menolak plus melapor memutus rantai pungli."},
{id:"TKP-2285", q:"Anda menemukan rekan ASN menyebarkan video ceramah yang menghasut membenci aparat negara. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan penyebaran hasutan tersebut ke pimpinan/aparat", s:5},{t:"Menasihati rekan agar berhenti menyebarkannya", s:4},{t:"Mengabaikannya karena sudah banyak yang menyebar", s:3},{t:"Menonton videonya karena penasaran", s:2},{t:"Ikut menyebarkan video itu", s:1}], ex:"Hasutan kebencian pada aparat adalah provokasi berbahaya; ASN wajib melapor, bukan menonton diam-diam."},
{id:"TKP-2286", q:"Saat seleksi jabatan, panitia meminta Anda memberikan nilai tinggi untuk kandidat titipan pejabat. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan menilai seluruh kandidat secara objektif berbasis kompetensi", s:5},{t:"Menolak titipan dan menilai apa adanya", s:4},{t:"Memberi nilai sedang untuk semua kandidat", s:3},{t:"Menaikkan sedikit nilai kandidat titipan", s:2},{t:"Memberi nilai tertinggi untuk kandidat titipan", s:1}], ex:"Seleksi jabatan berbasis merit; titipan pejabat yang dipenuhi merusak sistem meritokrasi ASN."},
{id:"TKP-2287", q:"Atasan Anda memakai anggaran perjalanan dinas untuk menginap di hotel mewah melebihi standar. Sikap yang paling tepat adalah ....", opts:[{t:"Menyampaikan keberatan dan melaporkan pemborosan tersebut sesuai ketentuan", s:5},{t:"Mengingatkan tentang standar biaya perjalanan dinas", s:4},{t:"Diam karena itu hak atasan", s:3},{t:"Ikut menikmati fasilitas mewahnya", s:2},{t:"Ikut mengajukan hotel mewah untuk perjalanan Anda", s:1}], ex:"Standar biaya dinas mengikat semua level; pemborosan anggaran wajib diingatkan dan dilaporkan."},
{id:"TKP-2288", q:"Seorang warga etnis minoritas dilayani dengan kasar oleh petugas loket di kantor Anda. Sikap yang paling tepat adalah ....", opts:[{t:"Menegur petugas, melayani warga dengan ramah, dan melaporkan perilaku diskriminatif itu", s:5},{t:"Mengambil alih dan melayani warga tersebut dengan baik", s:4},{t:"Membiarkan karena takut menegur senior", s:3},{t:"Ikut bersikap dingin pada warga itu", s:2},{t:"Mendukung petugas karena sependapat", s:1}], ex:"Diskriminasi pelayanan melanggar asas keadilan; ASN wajib melayani semua warga tanpa kecuali."},
{id:"TKP-2289", q:"Anda diminta menghapus komentar kritis warga di media sosial resmi dinas agar citra pimpinan bagus. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menghapus kritik yang santun dan menindaklanjutinya sebagai masukan", s:5},{t:"Tidak menghapus dan membiarkan diskusi berjalan", s:4},{t:"Menghapus hanya komentar yang kasar", s:3},{t:"Menghapus semua komentar kritis", s:2},{t:"Menghapus dan memblokir akun pengkritik", s:1}], ex:"Kritik publik yang santun adalah masukan berharga; menghapusnya demi citra adalah anti-transparansi."},
{id:"TKP-2290", q:"Kelompok di kantor Anda menggalang dana 'jihad' yang ternyata disalurkan ke jaringan ekstrem. Sikap yang paling tepat adalah ....", opts:[{t:"Tidak ikut menyumbang dan melaporkan penggalangan mencurigakan itu ke aparat", s:5},{t:"Tidak ikut menyumbang", s:4},{t:"Menyumbang kecil agar tidak dicurigai", s:3},{t:"Menyumbang karena diajak teman dekat", s:2},{t:"Ikut menggalang dana tersebut", s:1}], ex:"Pendanaan jaringan ekstrem adalah terorisme; ASN wajib menolak dan melaporkannya ke aparat."},
{id:"TKP-2291", q:"Rekan Anda, Hendra, meminta Anda memalsukan surat keterangan sehat untuk keperluan mutasinya. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan menyarankan mengurus surat keterangan resmi di faskes", s:5},{t:"Menolak memalsukan dokumen", s:4},{t:"Menunda dengan alasan sibuk", s:3},{t:"Membuatkan tetapi tanpa tanda tangan", s:2},{t:"Membuatkan surat palsu tersebut", s:1}], ex:"Pemalsuan surat keterangan adalah tindak pidana; menolak plus mengarahkan ke jalur resmi wujud integritas."},
{id:"TKP-2292", q:"Atasan meminta Anda menandatangani pakta integritas yang isinya sudah diisi pihak lain tanpa Anda baca. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menandatangani sebelum membaca dan memahami seluruh isinya", s:5},{t:"Meminta waktu membaca sebelum menandatangani", s:4},{t:"Menandatangani karena percaya atasan", s:3},{t:"Menandatangani sambil membaca sekilas", s:2},{t:"Menandatangani tanpa membaca", s:1}], ex:"Pakta integritas adalah komitmen hukum; menandatangani tanpa membaca menghilangkan makna pertanggungjawabannya."},
{id:"TKP-2293", q:"Anda melihat spanduk kampanye dipasang di dalam area sekolah tempat Anda bertugas. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan dan meminta penertiban karena sekolah wajib netral", s:5},{t:"Meminta pemasang mencopot spanduk tersebut", s:4},{t:"Membiarkannya karena di luar jam belajar", s:3},{t:"Membiarkannya karena mendukung calonnya", s:2},{t:"Ikut memasang spanduk calon lain", s:1}], ex:"Satuan pendidikan adalah zona netral pemilu; ASN pendidik wajib menjaga netralitasnya."},
{id:"TKP-2294", q:"Seorang rekan menawarkan Anda investasi dengan imbal hasil tak wajar memakai nama koperasi dinas. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan dugaan penipuan berkedok koperasi ke pengurus/pimpinan", s:5},{t:"Menolak tawaran investasi tersebut", s:4},{t:"Mengabaikan tawaran itu", s:3},{t:"Ikut dengan modal kecil untuk coba-coba", s:2},{t:"Ikut berinvestasi dan mengajak rekan lain", s:1}], ex:"Imbal hasil tak wajar adalah ciri penipuan; mencatut nama koperasi dinas wajib dilaporkan."},
{id:"TKP-2295", q:"Anda mengetahui jadwal piket diubah sepihak oleh senior agar Anda selalu dapat giliran malam. Sikap yang paling tepat adalah ....", opts:[{t:"Menyampaikan keberatan secara santun dan meminta jadwal disusun adil dan transparan", s:5},{t:"Meminta penjelasan dan pembagian jadwal yang adil", s:4},{t:"Menerima saja demi menghindari konflik", s:3},{t:"Menukar diam-diam dengan rekan lain", s:2},{t:"Tidak masuk saat giliran malam sebagai protes", s:1}], ex:"Profesionalisme menuntut keadilan pembagian tugas; menyampaikan keberatan resmi lebih baik daripada mangkir."},
{id:"TKP-2296", q:"Di masjid kantor, penceramah mengajak jemaah tidak memilih dalam pemilu karena dianggap sistem kafir. Sikap yang paling tepat adalah ....", opts:[{t:"Tidak mengikuti ajakan dan melaporkan materi anti-demokrasi tersebut", s:5},{t:"Tidak mengikuti ajakannya dan tetap menggunakan hak pilih", s:4},{t:"Diam dan keluar dari masjid", s:3},{t:"Mendengarkan saja tanpa berkomentar", s:2},{t:"Ikut menyetujui dan golput", s:1}], ex:"Mengajak golput dengan dalih agama adalah paham menyimpang; ASN wajib menjaga demokrasi dan melapor."},
{id:"TKP-2297", q:"Bendahara pengeluaran meminta Anda mencarikan kuitansi fiktif untuk menutup selisih kas. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan permintaan kuitansi fiktif tersebut", s:5},{t:"Menolak membantu mencari kuitansi fiktif", s:4},{t:"Berpura-pura tidak bisa membantu", s:3},{t:"Membantu mencari tetapi tidak ikut menandatangani", s:2},{t:"Membantu mencarikan kuitansi fiktif", s:1}], ex:"Kuitansi fiktif adalah pemalsuan untuk korupsi; menolak plus melapor melindungi integritas keuangan negara."},
{id:"TKP-2298", q:"Atasan Anda terang-terangan mendukung calon tertentu di grup WhatsApp dinas. Sikap yang paling tepat adalah ....", opts:[{t:"Tidak ikut mendukung dan melaporkan politisasi grup dinas ke Bawaslu/KASN", s:5},{t:"Tidak menanggapi pesan politik tersebut", s:4},{t:"Keluar dari grup diam-diam", s:3},{t:"Ikut memberi emotikon dukungan", s:2},{t:"Ikut berkampanye di grup", s:1}], ex:"Grup dinas adalah fasilitas negara yang wajib netral; politisasinya oleh atasan pun wajib dilaporkan."},
{id:"TKP-2299", q:"Anda diminta menjadi bendahara arisan online yang ternyata skema ponzi berkedok komunitas ASN. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan dugaan skema ponzi tersebut", s:5},{t:"Menolak menjadi bendahara", s:4},{t:"Mengabaikan tawaran itu", s:3},{t:"Ikut sebagai peserta dengan modal kecil", s:2},{t:"Menerima dan mengajak rekan bergabung", s:1}], ex:"Skema ponzi merugikan banyak orang; ASN tidak boleh terlibat apalagi menjadi pengurusnya."},
{id:"TKP-2300", q:"Seorang rekan mengajak Anda menonton kajian online yang mengajarkan kebencian pada Pancasila. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan konten anti-Pancasila tersebut ke pimpinan/aparat", s:5},{t:"Menolak ajakan menontonnya", s:4},{t:"Menonton sekilas lalu menutupnya", s:3},{t:"Menonton sampai selesai karena penasaran", s:2},{t:"Ikut menonton rutin dan menyebarkannya", s:1}], ex:"Konten anti-Pancasila adalah ancaman ideologi negara; ASN wajib menolak dan melaporkannya."},
{id:"TKP-2301", q:"Anda bertugas di kelurahan. Seorang warga meminta surat domisili palsu untuk syarat kredit bank dengan imbalan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan upaya pemalsuan dokumen tersebut", s:5},{t:"Menolak dan menjelaskan syarat domisili yang benar", s:4},{t:"Mengabaikan permintaan itu", s:3},{t:"Menolak imbalan tetapi tetap membuatkan suratnya", s:2},{t:"Membuatkan surat palsu demi imbalan", s:1}], ex:"Surat domisili palsu adalah pemalsuan dokumen negara; menolak plus melapor menjaga integritas pelayanan."},
{id:"TKP-2302", q:"Atasan Anda meminta Anda memprioritaskan rekrutmen tenaga honorer dari daerah asalnya tanpa seleksi. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan menuntut proses rekrutmen terbuka berbasis kompetensi", s:5},{t:"Menolak titipan dan tetap memakai mekanisme seleksi", s:4},{t:"Menyerahkan keputusan pada atasan", s:3},{t:"Meloloskan satu-dua orang titipan", s:2},{t:"Meloloskan semua titipan atasan", s:1}], ex:"Rekrutmen harus merit-based; nepotisme daerah merusak keadilan dan profesionalisme birokrasi."},
{id:"TKP-2303", q:"Rekan Anda, Joko, ketahuan menjual soal ujian dinas kepada peserta. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan penjualan soal ujian tersebut ke panitia/inspektorat", s:5},{t:"Menegur Joko dan memintanya berhenti", s:4},{t:"Berpura-pura tidak tahu", s:3},{t:"Membeli soalnya untuk persiapan Anda", s:2},{t:"Ikut menjual soal bersamanya", s:1}], ex:"Menjual soal ujian adalah kecurangan sistemik; melaporkannya melindungi integritas penilaian."},
{id:"TKP-2304", q:"Dalam rapat, diusulkan agar dana CSR perusahaan dialihkan ke rekening pribadi pengurus dengan dalih operasional. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan meminta dana CSR dikelola transparan sesuai peruntukannya", s:5},{t:"Menolak usulan pengalihan tersebut", s:4},{t:"Diam karena bukan bidang Anda", s:3},{t:"Setuju asalkan Anda tidak ikut menandatangani", s:2},{t:"Mendukung usulan tersebut", s:1}], ex:"Pengalihan dana CSR ke rekening pribadi adalah penggelapan; transparansi wajib ditegakkan."},
{id:"TKP-2305", q:"Anda melihat poster ajakan bergabung dengan kelompok separatis tertempel di papan pengumuman kantor. Sikap yang paling tepat adalah ....", opts:[{t:"Mencopot poster, mengamankannya sebagai bukti, dan melaporkannya ke pimpinan/aparat", s:5},{t:"Mencopot poster tersebut", s:4},{t:"Membiarkannya karena takut", s:3},{t:"Memfoto untuk koleksi pribadi", s:2},{t:"Ikut menyebarkan ajakannya", s:1}], ex:"Propaganda separatis di fasilitas negara adalah ancaman serius; mengamankan bukti dan melapor adalah kewajiban."},
{id:"TKP-2306", q:"Seorang notaris menawarkan Anda komisi tiap pengurusan balik nama yang Anda arahkan ke kantornya. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan tawaran komisi tersebut", s:5},{t:"Menolak dan tetap melayani warga tanpa arahan khusus", s:4},{t:"Mengabaikan tawaran itu", s:3},{t:"Menolak komisi tetapi tetap mengarahkan warga ke sana", s:2},{t:"Menerima dan mengarahkan warga ke notaris itu", s:1}], ex:"Komisi pengarahan layanan adalah gratifikasi terselubung; pelayanan harus netral tanpa arahan berkepentingan."},
{id:"TKP-2307", q:"Atasan meminta Anda menghapus data kehadiran elektronik yang menunjukkan kemangkirannya. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menghapus data dan melaporkan permintaan tersebut", s:5},{t:"Menolak menghapus data kehadiran", s:4},{t:"Berpura-pura sistem sedang error", s:3},{t:"Menghapus sebagian datanya", s:2},{t:"Menghapus data sesuai perintah", s:1}], ex:"Data kehadiran adalah dokumen resmi; menghapusnya untuk menutupi kemangkiran adalah pemalsuan."},
{id:"TKP-2308", q:"Anda diminta menjadi saksi nikah siri yang tidak tercatat resmi oleh rekan kerja. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dengan baik dan menyarankan pencatatan resmi sesuai UU Perkawinan", s:5},{t:"Menolak menjadi saksi", s:4},{t:"Menunda jawaban sampai dia lupa", s:3},{t:"Setuju asalkan tidak ada dokumen", s:2},{t:"Setuju demi persahabatan", s:1}], ex:"ASN memberi teladan tertib administrasi; pernikahan wajib tercatat resmi demi kepastian hukum."},
{id:"TKP-2309", q:"Seorang pengusaha tambang ilegal meminta Anda 'menutup mata' atas operasinya dengan imbalan bulanan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan tambang ilegal tersebut ke aparat/Dinas ESDM", s:5},{t:"Menolak tawaran dan tetap menjalankan pengawasan", s:4},{t:"Tidak menanggapi tawarannya", s:3},{t:"Menolak imbalan tetapi membiarkan operasinya", s:2},{t:"Menerima imbalan bulanan", s:1}], ex:"Tambang ilegal merusak lingkungan dan merugikan negara; menutup mata demi imbalan adalah korupsi."},
{id:"TKP-2310", q:"Rekan Anda, Dewi, menyebarkan daftar nama ASN yang dituduh 'antek asing' tanpa bukti di grup kantor. Sikap yang paling tepat adalah ....", opts:[{t:"Menegur Dewi, meminta bukti, dan melaporkan fitnah tersebut", s:5},{t:"Menegur Dewi agar menghapus tuduhannya", s:4},{t:"Diam karena nama Anda tidak disebut", s:3},{t:"Ikut meneruskan daftarnya", s:2},{t:"Menambah nama lain ke daftar itu", s:1}], ex:"Tuduhan tanpa bukti adalah fitnah yang memecah belah; ASN wajib menegakkan kebenaran dan melapor."},
{id:"TKP-2311", q:"Anda diminta panitia 17 Agustus memungut iuran 'wajib' dari pedagang kaki lima untuk acara kantor. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak memungut dan mengusulkan pendanaan resmi dari anggaran kegiatan", s:5},{t:"Menolak ikut memungut iuran tersebut", s:4},{t:"Ikut memungut tetapi tidak menikmati hasilnya", s:3},{t:"Memungut dengan nominal kecil saja", s:2},{t:"Ikut memungut dan menikmati hasilnya", s:1}], ex:"Pungutan liar berkedok acara adalah pungli; pendanaan kegiatan wajib dari sumber resmi yang akuntabel."},
{id:"TKP-2312", q:"Atasan Anda memerintahkan Anda mencoblos calon tertentu saat pemilu dengan dalih loyalitas. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak perintah tersebut dan melaporkannya ke Bawaslu/KASN", s:5},{t:"Menolak dan tetap memilih sesuai hati nurani", s:4},{t:"Berpura-pura setuju tetapi memilih sendiri", s:3},{t:"Mengikuti perintah karena takut", s:2},{t:"Menuruti dan mengajak rekan lain", s:1}], ex:"Hak pilih bersifat bebas dan rahasia; perintah mencoblos melanggar netralitas dan wajib dilaporkan."},
{id:"TKP-2313", q:"Seorang rekan mengajak Anda demo menolak kebijakan pemerintah yang sah dengan membawa atribut kantor. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak ikut dan menjelaskan ASN menyalurkan aspirasi lewat koridor resmi", s:5},{t:"Menolak ajakan demo tersebut", s:4},{t:"Tidak ikut tetapi tidak melarang", s:3},{t:"Ikut demo tanpa atribut kantor", s:2},{t:"Ikut demo dengan atribut kantor", s:1}], ex:"ASN dilarang demo menolak kebijakan dengan atribut dinas; aspirasi disalurkan lewat mekanisme resmi."},
{id:"TKP-2314", q:"Anda menemukan stempel palsu dinas dipakai rekan untuk memalsukan surat keterangan. Sikap yang paling tepat adalah ....", opts:[{t:"Mengamankan bukti dan melaporkan pemalsuan tersebut ke pimpinan/aparat", s:5},{t:"Menegur rekan dan memintanya berhenti", s:4},{t:"Berpura-pura tidak melihat", s:3},{t:"Meminta dibuatkan surat juga", s:2},{t:"Ikut menggunakan stempel palsu", s:1}], ex:"Pemalsuan stempel dinas adalah tindak pidana serius; mengamankan bukti dan melapor adalah kewajiban."},
{id:"TKP-2315", q:"Warga menawarkan Anda tanah murah bila bersedia 'mengurus' sengketa tanahnya hingga menang. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan menjelaskan sengketa diselesaikan lewat prosedur hukum yang berlaku", s:5},{t:"Menolak tawaran tersebut", s:4},{t:"Mengabaikan tawarannya", s:3},{t:"Menolak tanah tetapi memberi bocoran strategi", s:2},{t:"Menerima dan mengupayakan kemenangannya", s:1}], ex:"Sengketa tanah diputus lewat hukum, bukan imbalan; ASN tidak boleh menjadi makelar perkara."},
{id:"TKP-2316", q:"Di kantin kantor, sekelompok ASN rutin membahas rencana menolak upacara bendera karena dianggap bidah. Sikap yang paling tepat adalah ....", opts:[{t:"Tidak ikut, menjelaskan makna upacara, dan melaporkan paham menyimpang tersebut", s:5},{t:"Tidak ikut serta dalam pembahasan itu", s:4},{t:"Diam dan pindah meja", s:3},{t:"Mendengarkan karena penasaran", s:2},{t:"Ikut setuju menolak upacara", s:1}], ex:"Upacara bendera adalah wujud nasionalisme; paham yang menolaknya adalah radikalisme yang wajib dilaporkan."},
{id:"TKP-2317", q:"Bendahara meminta Anda ikut menandatangani laporan yang nominalnya sudah digelembungkan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menandatangani dan melaporkan penggelembungan tersebut", s:5},{t:"Menolak menandatangani laporan itu", s:4},{t:"Menunda tanda tangan", s:3},{t:"Menandatangani tetapi mencatat keberatan lisan", s:2},{t:"Menandatangani demi kebersamaan", s:1}], ex:"Menandatangani laporan yang digelembungkan berarti ikut korupsi; tolak dan laporkan."},
{id:"TKP-2318", q:"Seorang caleg meminta Anda menjadi koordinator pemilih di TPS dekat kantor dengan bayaran. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan upaya melibatkan ASN dalam mesin politik", s:5},{t:"Menolak tawaran tersebut", s:4},{t:"Mengabaikan tawarannya", s:3},{t:"Menolak bayaran tetapi membantu sukarela", s:2},{t:"Menerima tawaran tersebut", s:1}], ex:"Menjadi koordinator pemilih caleg melanggar netralitas ASN; wajib ditolak dan dilaporkan."},
{id:"TKP-2319", q:"Anda melihat rekan, Maya, mengambil foto soal ujian CPNS dengan ponselnya. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan kecurangan tersebut ke pengawas panitia seleksi", s:5},{t:"Menegur Maya dan memintanya menghapus foto", s:4},{t:"Berpura-pura tidak melihat", s:3},{t:"Meminta dikirimi fotonya", s:2},{t:"Ikut memotret soal", s:1}], ex:"Memotret soal ujian adalah kecurangan berat; melaporkannya menjaga keadilan seleksi."},
{id:"TKP-2320", q:"Atasan meminta Anda membuat akun media sosial anonim untuk menyerang kritik terhadap dinas. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak karena ASN menyampaikan klarifikasi lewat saluran resmi, bukan akun anonim", s:5},{t:"Menolak membuat akun anonim tersebut", s:4},{t:"Menunda dengan alasan tidak paham teknologi", s:3},{t:"Membuat akun tetapi tidak aktif menyerang", s:2},{t:"Membuat dan aktif menyerang pengkritik", s:1}], ex:"Klarifikasi resmi lewat humas, bukan buzzer anonim; ASN menjaga etika komunikasi publik."},
{id:"TKP-2321", q:"Seorang pengusaha hiburan malam meminta Anda memperlancar izinnya yang melanggar Perda dengan imbalan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan memproses izin sesuai Perda yang berlaku", s:5},{t:"Menolak tawaran tersebut", s:4},{t:"Mengabaikan tawarannya", s:3},{t:"Menolak imbalan tetapi melonggarkan syarat", s:2},{t:"Menerima dan meloloskan izin", s:1}], ex:"Perizinan wajib taat Perda; imbalan untuk melonggarkan syarat adalah suap."},
{id:"TKP-2322", q:"Rekan Anda, Agus, terang-terangan menyimpan senjata tajam di laci meja untuk 'jaga-jaga' aksi kelompoknya. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan temuan senjata tajam tersebut ke pimpinan/keamanan/aparat", s:5},{t:"Menegur Agus dan memintanya menyingkirkan senjata itu", s:4},{t:"Menjauhinya tanpa berbuat apa-apa", s:3},{t:"Diam karena takut padanya", s:2},{t:"Ikut menyimpan senjata serupa", s:1}], ex:"Senjata tajam di lingkungan kerja adalah ancaman keamanan; wajib dilaporkan segera ke aparat."},
{id:"TKP-2323", q:"Anda diminta mengosongkan kolom 'asal dana' pada laporan hibah agar tidak terlacak. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan mengisi laporan hibah secara lengkap dan transparan", s:5},{t:"Menolak mengosongkan kolom tersebut", s:4},{t:"Mengisi dengan keterangan samar", s:3},{t:"Mengosongkan sebagian saja", s:2},{t:"Mengosongkan sesuai permintaan", s:1}], ex:"Transparansi asal dana hibah mencegah pencucian uang; mengosongkannya adalah pelanggaran akuntabilitas."},
{id:"TKP-2324", q:"Saat kampanye, tim sukses membagikan sembako memakai kendaraan dinas kantor Anda. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan penyalahgunaan kendaraan dinas untuk kampanye ke Bawaslu/pimpinan", s:5},{t:"Menegur dan meminta kendaraan dikembalikan", s:4},{t:"Diam karena takut pada tim sukses", s:3},{t:"Membiarkannya karena kasihan pada warga", s:2},{t:"Ikut membantu membagikan sembako", s:1}], ex:"Kendaraan dinas untuk kampanye adalah pelanggaran netralitas dan penyalahgunaan aset negara."},
{id:"TKP-2325", q:"Seorang rekan meminta Anda menjadi penjamin kreditnya di bank dengan mencantumkan jabatan Anda. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak karena risiko hukum dan pencatutan jabatan dilarang", s:5},{t:"Menolak dengan alasan pribadi", s:4},{t:"Menunda jawaban terus-menerus", s:3},{t:"Setuju asalkan tidak ada surat resmi", s:2},{t:"Setuju demi membantu teman", s:1}], ex:"Menjadi penjamin memakai jabatan berisiko hukum dan mencoreng nama instansi; tolak tegas."},
{id:"TKP-2326", q:"Anda menemukan ceramah online yang mengajarkan ASN boleh berkhianat pada negara demi kelompoknya. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak pahamnya dan melaporkan konten tersebut ke aparat/BNPT", s:5},{t:"Tidak mengikuti ajarannya", s:4},{t:"Menutup videonya tanpa berbuat apa-apa", s:3},{t:"Menyimpan tautannya untuk dibahas teman", s:2},{t:"Ikut menyebarkannya", s:1}], ex:"Ajakan berkhianat pada negara adalah makar; ASN wajib menolak dan melaporkannya."},
{id:"TKP-2327", q:"Atasan meminta Anda memalsukan tanggal surat agar pengadaan terlihat tepat waktu. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak memalsukan tanggal dan mencatat sesuai fakta", s:5},{t:"Menolak mengubah tanggal surat", s:4},{t:"Menyerahkan ke staf lain", s:3},{t:"Mengubah tanggal sedikit saja", s:2},{t:"Mengubah tanggal sesuai perintah", s:1}], ex:"Pemalsuan tanggal dokumen adalah pemalsuan; fakta administrasi tidak boleh direkayasa."},
{id:"TKP-2328", q:"Seorang warga difabel dipersulit mengurus KTP oleh petugas dengan alasan 'ribet'. Sikap yang paling tepat adalah ....", opts:[{t:"Menegur petugas, membantu warga difabel mengurus KTP, dan melaporkan bila berulang", s:5},{t:"Membantu warga difabel tersebut mengurus KTP", s:4},{t:"Membiarkan karena bukan loket Anda", s:3},{t:"Ikut menganggapnya merepotkan", s:2},{t:"Menyuruh warga pulang dan datang lain waktu", s:1}], ex:"Pelayanan inklusif adalah kewajiban; mempersulit warga difabel melanggar asas keadilan pelayanan publik."},
{id:"TKP-2329", q:"Anda ditawari jabatan eselon dengan syarat menyetor sejumlah uang ke 'tim'. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan praktik jual beli jabatan tersebut", s:5},{t:"Menolak tawaran itu", s:4},{t:"Mengabaikan tawarannya", s:3},{t:"Menolak setor tetapi meminta dipertimbangkan", s:2},{t:"Menyetor demi jabatan", s:1}], ex:"Jual beli jabatan adalah korupsi; jabatan ASN diperoleh lewat merit, bukan setoran."},
{id:"TKP-2330", q:"Rekan Anda, Siti, mengajak Anda menandatangani surat pernyataan menolak vaksin dengan dalih konspirasi. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menandatangani dan menjelaskan pentingnya mengikuti kebijakan kesehatan resmi", s:5},{t:"Menolak menandatangani surat itu", s:4},{t:"Tidak menanggapi ajakannya", s:3},{t:"Menandatangani agar tidak dimusuhi", s:2},{t:"Ikut menggalang tanda tangan", s:1}], ex:"ASN menjadi teladan kepatuhan kebijakan publik; teori konspirasi tidak boleh disebarkan di lingkungan kerja."},
{id:"TKP-2331", q:"Dalam perjalanan dinas rombongan, panitia mengatur 'uang saku tambahan' dari selisih anggaran. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menerima dan melaporkan praktik selisih anggaran tersebut", s:5},{t:"Menolak menerima uang saku tambahan", s:4},{t:"Menerima tetapi tidak menggunakannya", s:3},{t:"Menerima karena semua peserta menerima", s:2},{t:"Menerima dan meminta ditambah", s:1}], ex:"Selisih anggaran yang dibagi-bagi adalah korupsi; menolak plus melapor menjaga integritas."},
{id:"TKP-2332", q:"Anda melihat atribut kampanye terpasang di ruang pelayanan publik kantor Anda. Sikap yang paling tepat adalah ....", opts:[{t:"Mencopot atribut dan melaporkan pelanggaran netralitas tersebut", s:5},{t:"Meminta atribut tersebut dicopot", s:4},{t:"Membiarkannya karena bukan Anda yang memasang", s:3},{t:"Membiarkannya karena mendukung calonnya", s:2},{t:"Ikut memasang atribut calon lain", s:1}], ex:"Ruang pelayanan publik wajib steril dari atribut kampanye; netralitas ASN ditegakkan di tempat kerja."},
{id:"TKP-2333", q:"Seorang kontraktor meminta Anda menaikkan volume pekerjaan dalam berita acara agar tagihannya lebih besar. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan mencatat volume sesuai hasil pemeriksaan fisik", s:5},{t:"Menolak menaikkan volume", s:4},{t:"Menunda penandatanganan", s:3},{t:"Menaikkan sedikit sebagai toleransi", s:2},{t:"Menaikkan sesuai permintaan", s:1}], ex:"Penggelembungan volume adalah mark-up; berita acara harus sesuai fakta pemeriksaan."},
{id:"TKP-2334", q:"Kelompok kajian di kantor Anda mengajarkan bahwa sumpah jabatan tidak mengikat bila pimpinan beda keyakinan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak paham tersebut dan melaporkan kajian menyimpang itu", s:5},{t:"Tidak mengikuti kajian tersebut", s:4},{t:"Diam agar tidak dicap tidak religius", s:3},{t:"Ikut hadir sesekali", s:2},{t:"Ikut menyebarkan ajarannya", s:1}], ex:"Sumpah jabatan mengikat pada negara, bukan pada pribadi pimpinan; paham sebaliknya adalah radikalisme."},
{id:"TKP-2335", q:"Atasan meminta password email dinas Anda dengan alasan pemeriksaan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan menjelaskan pemeriksaan dilakukan lewat prosedur resmi TI, bukan meminta password", s:5},{t:"Menolak memberikan password", s:4},{t:"Memberikan tetapi segera menggantinya", s:3},{t:"Memberikan karena dia atasan", s:2},{t:"Memberikan beserta semua akun pribadi", s:1}], ex:"Password bersifat rahasia pribadi; pemeriksaan resmi tidak pernah meminta password pengguna."},
{id:"TKP-2336", q:"Anda mengetahui dana bantuan bencana disunat oknum sebelum sampai ke korban. Sikap yang paling tepat adalah ....", opts:[{t:"Mengumpulkan bukti dan melaporkannya lewat WBS/inspektorat/aparat", s:5},{t:"Melaporkan temuan tersebut ke pimpinan", s:4},{t:"Diam karena takut pada oknum", s:3},{t:"Meminta bagian agar diam", s:2},{t:"Ikut menyunat dana bantuan", s:1}], ex:"Korupsi dana bencana adalah kejahatan kemanusiaan; whistleblowing adalah jalur pelaporan yang dilindungi."},
{id:"TKP-2337", q:"Seorang rekan ASN memposting foto surat suara yang sudah dicoblos saat pemilu. Sikap yang paling tepat adalah ....", opts:[{t:"Menasihati agar menghapus dan melaporkan pelanggaran pemilu tersebut ke Bawaslu", s:5},{t:"Menasihati rekan agar menghapus postingannya", s:4},{t:"Mengabaikan postingannya", s:3},{t:"Menyukai postingannya", s:2},{t:"Ikut memposting foto surat suara Anda", s:1}], ex:"Memotret surat suara melanggar asas rahasia pemilu; ASN wajib menegakkan aturan pemilu."},
{id:"TKP-2338", q:"Anda diminta menjadi 'kaki tangan' menagih utang koperasi dengan cara mengintimidasi. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak tegas karena intimidasi melanggar hukum dan kode etik", s:5},{t:"Menolak ajakan tersebut", s:4},{t:"Menghindar setiap kali diajak", s:3},{t:"Ikut menagih tetapi dengan cara halus", s:2},{t:"Ikut mengintimidasi", s:1}], ex:"Penagihan wajib lewat jalur hukum; intimidasi oleh ASN adalah pelanggaran berat."},
{id:"TKP-2339", q:"Di grup alumni, beredar ajakan menyumbang untuk 'perjuangan' kelompok bersenjata. Sikap yang paling tepat adalah ....", opts:[{t:"Tidak menyumbang dan melaporkan ajakan tersebut ke aparat", s:5},{t:"Tidak ikut menyumbang", s:4},{t:"Keluar dari grup diam-diam", s:3},{t:"Menyumbang kecil agar tidak dicurigai", s:2},{t:"Ikut menyumbang dan mengajak teman", s:1}], ex:"Pendanaan kelompok bersenjata adalah terorisme; ASN wajib melaporkannya, bukan sekadar keluar grup."},
{id:"TKP-2340", q:"Atasan Anda menyuruh mengubah hasil survei kepuasan masyarakat agar terlihat bagus. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak memanipulasi data survei dan menyajikan hasil apa adanya", s:5},{t:"Menolak mengubah hasil survei", s:4},{t:"Menyerahkan data mentah tanpa analisis", s:3},{t:"Menaikkan sedikit skornya", s:2},{t:"Mengubah hasil sesuai perintah", s:1}], ex:"Survei kepuasan adalah instrumen akuntabilitas; memanipulasinya menipu publik dan pimpinan."},
{id:"TKP-2341", q:"Seorang pasien meminta Anda mendahulukan keluarganya dalam antrean layanan dengan imbalan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan menjelaskan antrean berdasarkan prioritas medis", s:5},{t:"Menolak tawaran tersebut", s:4},{t:"Mengabaikan tawarannya", s:3},{t:"Menolak imbalan tetapi mendahulukan keluarganya", s:2},{t:"Menerima dan mendahulukan", s:1}], ex:"Prioritas layanan kesehatan ditentukan medis, bukan imbalan; gratifikasi di faskes dilarang."},
{id:"TKP-2342", q:"Rekan Anda, Dedi, memasang kamera tersembunyi di ruang ganti kantor untuk iseng. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan perbuatan tersebut ke pimpinan/keamanan karena melanggar privasi dan hukum", s:5},{t:"Menegur Dedi dan memintanya mencopot kamera", s:4},{t:"Menghindar dari ruang ganti itu", s:3},{t:"Diam karena takut", s:2},{t:"Ikut menonton hasil rekamannya", s:1}], ex:"Kamera tersembunyi di ruang ganti adalah pelanggaran privasi dan pidana; wajib dilaporkan."},
{id:"TKP-2343", q:"Anda diminta menandatangani surat perintah tugas untuk kegiatan yang sudah selesai dilaksanakan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menandatangani dokumen backdate dan meminta dibuat sesuai fakta", s:5},{t:"Menolak menandatangani surat tersebut", s:4},{t:"Menunda tanda tangan", s:3},{t:"Menandatangani dengan tanggal sebenarnya", s:2},{t:"Menandatangani sesuai permintaan", s:1}], ex:"Dokumen backdate adalah pemalsuan administrasi; tanda tangan hanya untuk fakta yang benar."},
{id:"TKP-2344", q:"Seorang ormas meminta Anda menutup paksa tempat ibadah minoritas dengan dalih menjaga ketertiban. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan menjelaskan kebebasan beribadah dijamin konstitusi serta melapor bila ada ancaman", s:5},{t:"Menolak permintaan penutupan tersebut", s:4},{t:"Menunda keputusan tanpa alasan", s:3},{t:"Menutup sementara demi meredam massa", s:2},{t:"Menuruti permintaan ormas", s:1}], ex:"Penutupan tempat ibadah oleh tekanan massa adalah intoleransi; ASN menegakkan konstitusi, bukan tunduk pada tekanan."},
{id:"TKP-2345", q:"Atasan meminta Anda mengalihkan anggaran ATK untuk membeli hadiah perpisahannya. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak karena anggaran ATK tidak boleh dialihkan untuk kepentingan pribadi", s:5},{t:"Menolak permintaan tersebut", s:4},{t:"Mengusulkan patungan sukarela rekan", s:3},{t:"Mengalihkan sebagian kecil saja", s:2},{t:"Mengalihkan sesuai perintah", s:1}], ex:"Pengalihan anggaran di luar peruntukan adalah penyalahgunaan; hadiah pribadi bukan belanja negara."},
{id:"TKP-2346", q:"Anda melihat rekan ASN membagikan amplop berisi uang kepada warga menjelang pencoblosan. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan praktik politik uang tersebut ke Bawaslu/pimpinan", s:5},{t:"Menegur rekan agar berhenti", s:4},{t:"Berpura-pura tidak melihat", s:3},{t:"Menerima amplop yang ditawarkan ke Anda", s:2},{t:"Ikut membagikan amplop", s:1}], ex:"Politik uang adalah pelanggaran pidana pemilu; ASN yang melihat wajib melaporkannya."},
{id:"TKP-2347", q:"Seorang vendor menawarkan Anda jalan-jalan gratis bila kontraknya diperpanjang tanpa evaluasi. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan memastikan perpanjangan kontrak lewat evaluasi kinerja resmi", s:5},{t:"Menolak tawaran jalan-jalan tersebut", s:4},{t:"Mengabaikan tawarannya", s:3},{t:"Menolak jalan-jalan tetapi memperpanjang kontraknya", s:2},{t:"Menerima dan memperpanjang kontrak", s:1}], ex:"Perpanjangan kontrak wajib berbasis evaluasi; iming-iming vendor adalah gratifikasi yang merusak objektivitas."},
{id:"TKP-2348", q:"Rekan Anda, Nur, mengajak Anda mogok kerja massal menolak mutasi yang sah. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak ikut mogok dan menyarankan keberatan lewat jalur resmi kepegawaian", s:5},{t:"Menolak ajakan mogok tersebut", s:4},{t:"Tidak ikut tetapi tidak melarang", s:3},{t:"Ikut mogok sehari sebagai solidaritas", s:2},{t:"Ikut mengorganisasi mogok", s:1}], ex:"Mogok menolak mutasi sah melanggar disiplin; keberatan ASN disalurkan lewat mekanisme kepegawaian resmi."},
{id:"TKP-2349", q:"Anda menemukan buku panduan 'khilafah' disebarkan di perpustakaan kantor. Sikap yang paling tepat adalah ....", opts:[{t:"Mengamankan buku sebagai bukti dan melaporkannya ke pimpinan/aparat", s:5},{t:"Menarik buku tersebut dari perpustakaan", s:4},{t:"Membiarkannya karena hanya buku", s:3},{t:"Membaca untuk menambah wawasan", s:2},{t:"Ikut menyebarkannya", s:1}], ex:"Propaganda khilafah bertentangan dengan Pancasila; penyebarannya di fasilitas negara wajib dilaporkan."},
{id:"TKP-2350", q:"Atasan meminta Anda memalsukan absensi kehadirannya saat ia cuti tanpa izin. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak memalsukan absensi siapa pun dan melaporkan bila dipaksa", s:5},{t:"Menolak memalsukan absensi", s:4},{t:"Berpura-pura tidak bisa mengakses sistem", s:3},{t:"Memalsukan untuk satu hari saja", s:2},{t:"Memalsukan sesuai permintaan", s:1}], ex:"Absensi adalah dokumen kedinasan; memalsukannya — untuk siapa pun — adalah pelanggaran disiplin dan hukum."},
{id:"TKP-2351", q:"Seorang pengusaha katering hajatan meminta Anda menerbitkan sertifikat laik higiene tanpa inspeksi dengan imbalan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melakukan inspeksi sesuai prosedur sebelum menerbitkan sertifikat", s:5},{t:"Menolak tawaran dan tetap mensyaratkan inspeksi", s:4},{t:"Mengabaikan tawarannya", s:3},{t:"Menolak imbalan tetapi menerbitkan tanpa inspeksi", s:2},{t:"Menerima dan menerbitkan sertifikat", s:1}], ex:"Sertifikasi tanpa inspeksi membahayakan kesehatan publik; integritas menuntut prosedur dijalankan penuh."},
{id:"TKP-2352", q:"Rekan Anda, Fajar, ketahuan mengedit nilai SKP miliknya di sistem agar terlihat baik. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan manipulasi data SKP tersebut ke atasan/BKPSDM", s:5},{t:"Menegur Fajar dan memintanya memperbaiki", s:4},{t:"Berpura-pura tidak tahu", s:3},{t:"Meminta diajari cara mengeditnya", s:2},{t:"Ikut mengedit SKP Anda", s:1}], ex:"SKP adalah dasar penilaian kinerja; memanipulasinya merusak meritokrasi dan wajib dilaporkan."},
{id:"TKP-2353", q:"Anda diminta menjadi moderator diskusi yang ternyata forum perekrutan ideologi ekstrem. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menjadi moderator dan melaporkan forum tersebut", s:5},{t:"Menolak tawaran menjadi moderator", s:4},{t:"Menerima tetapi bersikap pasif", s:3},{t:"Menerima karena butuh pengalaman", s:2},{t:"Menerima dan aktif memoderasi", s:1}], ex:"Memfasilitasi forum ekstrem sama dengan mendukungnya; ASN wajib menolak dan melapor."},
{id:"TKP-2354", q:"Atasan meminta Anda menutupi kasus asusila yang melibatkan pejabat dinas agar tidak viral. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menutupi dan mendorong penyelesaian lewat mekanisme hukum/disiplin resmi", s:5},{t:"Menolak terlibat dalam penutupan kasus", s:4},{t:"Diam dan tidak ikut campur", s:3},{t:"Ikut menutupi dengan imbalan", s:2},{t:"Aktif membantu menutupi kasus", s:1}], ex:"Menutupi pelanggaran hukum demi citra adalah obstruction; ASN menegakkan kebenaran lewat jalur resmi."},
{id:"TKP-2355", q:"Seorang calo SIM menawarkan Anda 'paket lulus' untuk kerabat dengan harga tertentu. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan praktik percaloan tersebut", s:5},{t:"Menolak dan menyarankan ikut ujian resmi", s:4},{t:"Mengabaikan tawarannya", s:3},{t:"Menolak tetapi memberi tahu calo lain yang lebih murah", s:2},{t:"Membeli paket untuk kerabat", s:1}], ex:"Percaloan SIM adalah pungli; menolak plus mengarahkan ke jalur resmi melindungi publik."},
{id:"TKP-2356", q:"Anda melihat dana bos sekolah dipakai kepala sekolah untuk renovasi rumah pribadinya. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan penyalahgunaan dana BOS ke dinas pendidikan/inspektorat", s:5},{t:"Menegur kepala sekolah agar menghentikan", s:4},{t:"Diam karena takut dimutasi", s:3},{t:"Meminta ikut menikmati hasilnya", s:2},{t:"Ikut membantu menutupi", s:1}], ex:"Dana BOS untuk pendidikan, bukan pribadi; penyalahgunaannya adalah korupsi yang wajib dilaporkan."},
{id:"TKP-2357", q:"Rekan Anda mengajak Anda menandatangani petisi dukungan untuk ormas yang dibubarkan pemerintah. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menandatangani dan melaporkan bila petisi disebar di lingkungan kerja", s:5},{t:"Menolak menandatangani petisi tersebut", s:4},{t:"Tidak menanggapi ajakan itu", s:3},{t:"Menandatangani agar tidak dimusuhi", s:2},{t:"Ikut menggalang tanda tangan", s:1}], ex:"Mendukung ormas terlarang bertentangan dengan keputusan negara; ASN wajib setia pada hukum."},
{id:"TKP-2358", q:"Atasan meminta Anda menghapus rekaman CCTV yang merekam pungli di loket pelayanan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menghapus bukti dan melaporkan perintah tersebut", s:5},{t:"Menolak menghapus rekaman CCTV", s:4},{t:"Berpura-pura tidak tahu cara menghapus", s:3},{t:"Menghapus sebagian rekaman", s:2},{t:"Menghapus sesuai perintah", s:1}], ex:"Menghapus bukti pungli adalah perintangan penyidikan; bukti wajib dijaga dan dilaporkan."},
{id:"TKP-2359", q:"Seorang warga menawarkan Anda menjadi makelar tanah kas desa dengan komisi besar. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan tawaran tersebut karena tanah kas desa tidak boleh diperjualbelikan", s:5},{t:"Menolak tawaran tersebut", s:4},{t:"Mengabaikan tawarannya", s:3},{t:"Menolak komisi tetapi membantu prosesnya", s:2},{t:"Menerima tawaran itu", s:1}], ex:"Tanah kas desa adalah aset negara; memperjualbelikannya adalah pelanggaran hukum berat."},
{id:"TKP-2360", q:"Anda diminta panitia lomba 17 Agustus menjadi juri yang memenangkan anak pejabat. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan menilai seluruh peserta secara objektif", s:5},{t:"Menolak titipan dan menilai adil", s:4},{t:"Memberi nilai sama rata semua peserta", s:3},{t:"Memenangkan anak pejabat dengan selisih tipis", s:2},{t:"Memenangkan anak pejabat sesuai permintaan", s:1}], ex:"Penjurian harus objektif; titipan pejabat merusak sportivitas dan integritas panitia."},
{id:"TKP-2361", q:"Rekan Anda, Ratna, menyebarkan foto editan yang memfitnah pimpinan dinas di grup kantor. Sikap yang paling tepat adalah ....", opts:[{t:"Menegur Ratna, memintanya menghapus, dan melaporkan penyebaran fitnah tersebut", s:5},{t:"Menegur Ratna agar menghapus foto fitnah itu", s:4},{t:"Diam karena tidak menyukai pimpinan juga", s:3},{t:"Ikut meneruskan foto itu", s:2},{t:"Menambah narasi fitnah baru", s:1}], ex:"Fitnah lewat foto editan melanggar UU ITE; ASN menyelesaikan masalah lewat jalur resmi, bukan fitnah."},
{id:"TKP-2362", q:"Atasan Anda memerintahkan Anda ikut mengawal kampanye calon tertentu memakai seragam dinas. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak memakai seragam untuk kampanye dan melaporkan perintah tersebut", s:5},{t:"Menolak ikut pengawalan kampanye", s:4},{t:"Ikut tetapi melepas atribut dinas", s:3},{t:"Ikut karena perintah atasan", s:2},{t:"Ikut aktif dengan seragam lengkap", s:1}], ex:"Seragam dinas tidak boleh dipakai untuk kampanye; perintah itu melanggar netralitas ASN."},
{id:"TKP-2363", q:"Seorang importir meminta Anda meloloskan barang tanpa pemeriksaan karantina dengan imbalan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan upaya suap karantina tersebut", s:5},{t:"Menolak dan tetap melakukan pemeriksaan", s:4},{t:"Mengabaikan tawarannya", s:3},{t:"Menolak imbalan tetapi meloloskan sebagian", s:2},{t:"Menerima dan meloloskan barang", s:1}], ex:"Karantina melindungi kesehatan dan keamanan nasional; meloloskannya demi suap membahayakan negara."},
{id:"TKP-2364", q:"Anda menemukan rekan ASN aktif berdakwah mengkafirkan sistem pemerintahan Indonesia. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan dakwah takfir terhadap negara tersebut ke pimpinan/aparat", s:5},{t:"Menasihati rekan agar berhenti", s:4},{t:"Menghindarinya tanpa berbuat apa-apa", s:3},{t:"Mendengarkan ceramahnya", s:2},{t:"Ikut menyebarkan dakwahnya", s:1}], ex:"Mengkafirkan sistem negara adalah paham ekstrem; ASN wajib melaporkannya demi keutuhan NKRI."},
{id:"TKP-2365", q:"Bendahara meminta Anda menyimpan uang kas kantor di rekening pribadi 'sementara'. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak tegas karena kas negara wajib di rekening resmi dan tercatat", s:5},{t:"Menolak menyimpan uang kas tersebut", s:4},{t:"Menunda dengan alasan belum punya rekening", s:3},{t:"Menyimpan sebagian kecil saja", s:2},{t:"Menyimpan sesuai permintaan", s:1}], ex:"Kas negara di rekening pribadi adalah penyalahgunaan; penolakan tegas melindungi dari jerat hukum."},
{id:"TKP-2366", q:"Seorang caleg meminta daftar hadir apel ASN untuk diklaim sebagai massa pendukungnya. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak memberikan dan melaporkan penyalahgunaan data apel tersebut", s:5},{t:"Menolak memberikan daftar hadir", s:4},{t:"Berpura-pura daftar belum direkap", s:3},{t:"Memberikan daftar yang sudah lama", s:2},{t:"Memberikan daftar hadir terbaru", s:1}], ex:"Data kedinasan bukan alat kampanye; memberikannya melanggar netralitas dan perlindungan data."},
{id:"TKP-2367", q:"Anda melihat petugas kebersihan disuruh membersihkan rumah pribadi atasan saat jam kerja. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan penyalahgunaan tenaga kerja tersebut ke pimpinan yang lebih tinggi", s:5},{t:"Menegur praktik tersebut secara santun", s:4},{t:"Diam karena bukan urusan Anda", s:3},{t:"Ikut menyuruhnya mengerjakan hal pribadi", s:2},{t:"Meminta petugas membersihkan rumah Anda juga", s:1}], ex:"Tenaga kerja negara hanya untuk kepentingan dinas; memakainya untuk pribadi adalah penyalahgunaan wewenang."},
{id:"TKP-2368", q:"Rekan Anda, Budi, mengajak Anda berinvestasi di 'koperasi' yang menjanjikan untung 20% per bulan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan dugaan investasi bodong tersebut", s:5},{t:"Menolak tawaran investasi itu", s:4},{t:"Mengabaikan ajakannya", s:3},{t:"Ikut dengan modal kecil", s:2},{t:"Ikut dan mengajak rekan lain", s:1}], ex:"Imbal hasil 20% per bulan adalah ciri investasi bodong; ASN tidak boleh terlibat apalagi merekrut."},
{id:"TKP-2369", q:"Atasan meminta Anda membuat surat tugas backdate untuk perjalanan yang sudah lama selesai. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak membuat surat backdate dan mencatat sesuai tanggal sebenarnya", s:5},{t:"Menolak membuat surat tersebut", s:4},{t:"Menunda pengerjaannya", s:3},{t:"Membuat dengan tanggal mendekati sebenarnya", s:2},{t:"Membuat sesuai permintaan", s:1}], ex:"Surat tugas backdate adalah pemalsuan administrasi; dokumen dinas wajib sesuai fakta waktu."},
{id:"TKP-2370", q:"Kelompok di kantor Anda merencanakan sweeping terhadap pedagang dari etnis tertentu. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak ikut dan melaporkan rencana sweeping diskriminatif itu ke pimpinan/aparat", s:5},{t:"Menolak ikut serta", s:4},{t:"Diam dan menjauh", s:3},{t:"Ikut menonton dari jauh", s:2},{t:"Ikut dalam sweeping", s:1}], ex:"Sweeping etnis adalah intoleransi dan main hakim sendiri; ASN wajib menolak dan melapor."},
{id:"TKP-2371", q:"Seorang pengusaha SPBU meminta Anda mengabaikan takaran yang tidak sesuai standar dengan imbalan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan pelanggaran metrologi tersebut", s:5},{t:"Menolak dan tetap melakukan tera ulang", s:4},{t:"Mengabaikan tawarannya", s:3},{t:"Menolak imbalan tetapi membiarkan pelanggaran", s:2},{t:"Menerima dan mengabaikan pelanggaran", s:1}], ex:"Takaran curang merugikan konsumen luas; pengawasan metrologi tidak boleh dibeli."},
{id:"TKP-2372", q:"Anda diminta menjadi bendahara pengajian yang dananya dipakai untuk kegiatan politik praktis. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak karena dana umat tidak boleh dipakai politik praktis dan melaporkannya", s:5},{t:"Menolak menjadi bendahara", s:4},{t:"Menerima tetapi tidak ikut mengelola", s:3},{t:"Menerima karena diajak tokoh", s:2},{t:"Menerima dan aktif mengelola", s:1}], ex:"Dana keagamaan untuk politik praktis adalah penyalahgunaan; ASN menjaga netralitas dan amanah."},
{id:"TKP-2373", q:"Rekan Anda, Andi, ketahuan memalsukan sertifikat pelatihan untuk syarat kenaikan pangkat. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan pemalsuan sertifikat tersebut ke BKPSDM/panitia", s:5},{t:"Menegur Andi dan memintanya menarik berkas", s:4},{t:"Berpura-pura tidak tahu", s:3},{t:"Meminta dibuatkan sertifikat juga", s:2},{t:"Ikut memalsukan sertifikat Anda", s:1}], ex:"Sertifikat palsu merusak meritokrasi; melaporkannya menjaga keadilan kenaikan pangkat."},
{id:"TKP-2374", q:"Atasan meminta Anda menandatangani kontrak dengan vendor yang belum jelas legalitasnya. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menandatangani sebelum verifikasi legalitas vendor selesai", s:5},{t:"Menolak dan meminta kelengkapan dokumen vendor", s:4},{t:"Menunda tanda tangan", s:3},{t:"Menandatangani dengan catatan lisan", s:2},{t:"Menandatangani karena perintah", s:1}], ex:"Kontrak dengan vendor tak jelas berisiko hukum dan korupsi; verifikasi adalah kewajiban sebelum tanda tangan."},
{id:"TKP-2375", q:"Anda melihat selebaran rekrutmen 'mujahid' ditempel di mading kantor. Sikap yang paling tepat adalah ....", opts:[{t:"Mencopot selebaran, mengamankan sebagai bukti, dan melaporkannya ke aparat", s:5},{t:"Mencopot selebaran tersebut", s:4},{t:"Membiarkannya karena takut", s:3},{t:"Memfoto untuk dibaca nanti", s:2},{t:"Ikut mendaftar", s:1}], ex:"Rekrutmen mujahid adalah perekrutan terorisme; mengamankan bukti dan melapor adalah kewajiban ASN."},
{id:"TKP-2376", q:"Seorang warga meminta Anda mempercepat sertifikat tanahnya yang bermasalah dengan imbalan besar. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan menjelaskan sengketa tanah diselesaikan lewat prosedur hukum", s:5},{t:"Menolak tawaran tersebut", s:4},{t:"Mengabaikan tawarannya", s:3},{t:"Menolak imbalan tetapi memberi jalan pintas", s:2},{t:"Menerima dan mengurusnya", s:1}], ex:"Sertifikat tanah bermasalah tidak boleh dipercepat dengan imbalan; integritas pertanahan dijaga."},
{id:"TKP-2377", q:"Atasan Anda menggunakan fasilitas rapat dinas untuk pertemuan tim suksesnya. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan penyalahgunaan fasilitas negara untuk kampanye", s:5},{t:"Menegur dan meminta tidak mengulangi", s:4},{t:"Diam karena takut", s:3},{t:"Membiarkannya karena mendukung calonnya", s:2},{t:"Ikut membantu menyiapkan ruangan", s:1}], ex:"Fasilitas negara untuk kampanye melanggar netralitas; penyalahgunaannya wajib dilaporkan."},
{id:"TKP-2378", q:"Rekan Anda, Siti, meminta Anda menggantikan ujian dinasnya dengan imbalan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan praktik joki ujian tersebut", s:5},{t:"Menolak tawaran menjadi joki", s:4},{t:"Mengabaikan tawarannya", s:3},{t:"Menolak tetapi merahasiakannya", s:2},{t:"Menerima menjadi joki", s:1}], ex:"Joki ujian dinas adalah kecurangan dan pemalsuan identitas peserta; wajib ditolak dan dilaporkan."},
{id:"TKP-2379", q:"Anda menemukan dokumen rahasia negara tercecer di ruang fotokopi. Sikap yang paling tepat adalah ....", opts:[{t:"Mengamankan dokumen dan menyerahkannya ke pejabat yang berwenang/pimpinan", s:5},{t:"Mengamankan dan menyerahkan ke atasan langsung", s:4},{t:"Membiarkannya di tempat", s:3},{t:"Memfotokopi untuk arsip pribadi", s:2},{t:"Menyebarkannya ke media sosial", s:1}], ex:"Dokumen rahasia wajib diamankan dan diserahkan ke pihak berwenang; menyebarkannya adalah pelanggaran hukum."},
{id:"TKP-2380", q:"Kelompok kajian kantor mengajarkan doa khusus agar pemimpin yang sah lengser. Sikap yang paling tepat adalah ....", opts:[{t:"Tidak ikut dan melaporkan kajian bermuatan politik menyimpang tersebut", s:5},{t:"Tidak mengikuti kajian itu", s:4},{t:"Diam dan keluar ruangan", s:3},{t:"Ikut hadir karena penasaran", s:2},{t:"Ikut mengaminkan doanya", s:1}], ex:"Kajian berkedok agama untuk makar adalah radikalisme; ASN wajib menolak dan melapor."},
{id:"TKP-2381", q:"Seorang supplier obat meminta Anda memenangkan tender RSUD dengan imbalan perjalanan umroh. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan tawaran suap tender tersebut", s:5},{t:"Menolak tawaran tersebut", s:4},{t:"Mengabaikan tawarannya", s:3},{t:"Menolak umroh tetapi memenangkan tendernya", s:2},{t:"Menerima dan memenangkan tender", s:1}], ex:"Suap tender obat membahayakan pasien dan keuangan negara; menolak plus melapor adalah integritas."},
{id:"TKP-2382", q:"Atasan meminta Anda memalsukan laporan kehadiran rapat yang tidak pernah diadakan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak memalsukan dan mencatat sesuai fakta", s:5},{t:"Menolak membuat laporan palsu", s:4},{t:"Menunda pengerjaannya", s:3},{t:"Membuat dengan peserta fiktif sedikit", s:2},{t:"Membuat sesuai permintaan", s:1}], ex:"Laporan kegiatan fiktif adalah korupsi anggaran; fakta administrasi tidak boleh direkayasa."},
{id:"TKP-2383", q:"Anda melihat baliho caleg dipasang menutupi papan informasi layanan publik. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan dan meminta penertiban karena papan layanan wajib steril", s:5},{t:"Meminta baliho dipindah", s:4},{t:"Membiarkannya", s:3},{t:"Membiarkannya karena mendukung calegnya", s:2},{t:"Ikut memasang baliho lain", s:1}], ex:"Papan informasi publik bukan tempat kampanye; ASN menegakkan netralitas fasilitas negara."},
{id:"TKP-2384", q:"Rekan Anda, Joko, menawarkan jasa 'pengurusan cepat' STNK dengan tarif di atas resmi. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan praktik percaloan tersebut", s:5},{t:"Menolak dan menyarankan jalur resmi", s:4},{t:"Mengabaikan tawarannya", s:3},{t:"Menggunakan jasanya sekali", s:2},{t:"Ikut menjadi calo bersamanya", s:1}], ex:"Percaloan layanan publik adalah pungli; ASN mengarahkan warga ke jalur resmi."},
{id:"TKP-2385", q:"Anda diminta menghapus jejak digital ujaran kebencian yang pernah diposting rekan ASN. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak membantu menghapus bukti dan menyarankan rekan mempertanggungjawabkannya", s:5},{t:"Menolak membantu", s:4},{t:"Berpura-pura tidak bisa", s:3},{t:"Membantu menghapus sebagian", s:2},{t:"Membantu menghapus semuanya", s:1}], ex:"Menghapus bukti pelanggaran adalah perintangan; setiap ASN bertanggung jawab atas jejak digitalnya."},
{id:"TKP-2386", q:"Atasan meminta Anda mengalokasikan proyek padat karya hanya untuk pendukungnya saat pemilu. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan mengalokasikan proyek sesuai kriteria penerima yang sah", s:5},{t:"Menolak permintaan tersebut", s:4},{t:"Menunda alokasi", s:3},{t:"Mengalokasikan sebagian untuk pendukungnya", s:2},{t:"Mengalokasikan sesuai perintah", s:1}], ex:"Proyek negara bukan alat politik; alokasi wajib berbasis kriteria, bukan dukungan politik."},
{id:"TKP-2387", q:"Seorang rekan mengajak Anda bergabung dengan milisi sipil bersenjata di luar tugas. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak tegas dan melaporkan ajakan tersebut ke aparat", s:5},{t:"Menolak ajakan itu", s:4},{t:"Mengabaikan ajakannya", s:3},{t:"Ikut latihan sekali", s:2},{t:"Bergabung dengan milisi itu", s:1}], ex:"Milisi bersenjata di luar hukum adalah ancaman keamanan; ASN wajib menolak dan melapor."},
{id:"TKP-2388", q:"Anda mengetahui honorarium narasumber digelembungkan dan selisihnya dibagi panitia. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menerima selisih dan melaporkan praktik tersebut", s:5},{t:"Menolak menerima bagian selisih", s:4},{t:"Menerima tetapi tidak menggunakannya", s:3},{t:"Menerima karena semua panitia menerima", s:2},{t:"Ikut mengatur pembagiannya", s:1}], ex:"Penggelembungan honorarium adalah korupsi; menolak bagian plus melapor menjaga integritas."},
{id:"TKP-2389", q:"Rekan Anda, Dewi, terang-terangan menolak bekerja sama dengan ASN nonmuslim dalam tim. Sikap yang paling tepat adalah ....", opts:[{t:"Menegur Dewi, menjelaskan profesionalisme tanpa diskriminasi, dan melaporkan bila berlanjut", s:5},{t:"Menegur Dewi agar bersikap profesional", s:4},{t:"Membiarkannya karena keyakinan pribadi", s:3},{t:"Ikut menjauhi rekan nonmuslim", s:2},{t:"Mendukung sikap Dewi", s:1}], ex:"Diskriminasi dalam tim kerja adalah intoleransi; profesionalisme ASN menuntut kerja sama tanpa SARA."},
{id:"TKP-2390", q:"Atasan meminta Anda menandatangani surat pernyataan tidak akan melapor ke mana pun tentang penyimpangan dinas. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menandatangani karena bertentangan dengan kewajiban melapor penyimpangan", s:5},{t:"Menolak menandatangani surat itu", s:4},{t:"Menunda tanda tangan", s:3},{t:"Menandatangani tetapi tetap melapor diam-diam", s:2},{t:"Menandatangani dan bungkam", s:1}], ex:"Surat bungkam tidak mengikat secara hukum; kewajiban melapor penyimpangan dilindungi UU."},
{id:"TKP-2391", q:"Seorang pengembang meminta Anda mengubah status lahan pertanian menjadi perumahan dengan imbalan. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan memproses alih fungsi sesuai RTRW yang berlaku", s:5},{t:"Menolak tawaran tersebut", s:4},{t:"Mengabaikan tawarannya", s:3},{t:"Menolak imbalan tetapi membantu memuluskan", s:2},{t:"Menerima dan mengubah status lahan", s:1}], ex:"Alih fungsi lahan wajib taat RTRW; imbalan untuk mengubahnya adalah suap perizinan."},
{id:"TKP-2392", q:"Anda melihat video rekan ASN sedang berorasi menolak Pancasila di sebuah aksi. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan video tersebut ke pimpinan/aparat sebagai bukti", s:5},{t:"Menasihati rekan agar berhenti", s:4},{t:"Mengabaikan video itu", s:3},{t:"Menyukai videonya", s:2},{t:"Ikut menyebarkan video itu", s:1}], ex:"Orasi menolak Pancasila oleh ASN adalah pelanggaran ideologi berat; wajib dilaporkan dengan bukti."},
{id:"TKP-2393", q:"Bendahara meminta Anda ikut menutupi kekurangan kas dengan membuat kuitansi fiktif. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan kekurangan kas serta permintaan fiktif tersebut", s:5},{t:"Menolak membantu menutupi", s:4},{t:"Berpura-pura sibuk", s:3},{t:"Membantu mencari kuitansi asli pengganti", s:2},{t:"Membantu membuat kuitansi fiktif", s:1}], ex:"Menutupi kekurangan kas dengan dokumen fiktif adalah penggelapan; tolak dan laporkan."},
{id:"TKP-2394", q:"Atasan meminta data siswa untuk kepentingan survei elektabilitas kerabatnya. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak memberikan data siswa dan melaporkan penyalahgunaan data tersebut", s:5},{t:"Menolak memberikan data siswa", s:4},{t:"Berpura-pura data belum siap", s:3},{t:"Memberikan data yang sudah lama", s:2},{t:"Memberikan data terbaru", s:1}], ex:"Data siswa dilindungi; memberikannya untuk survei politik melanggar privasi dan netralitas."},
{id:"TKP-2395", q:"Rekan Anda, Putri, mengajak Anda arisan berantai yang menjanjikan motor bagi yang merekrut anggota baru. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan dugaan skema piramida tersebut", s:5},{t:"Menolak ikut arisan itu", s:4},{t:"Mengabaikan ajakannya", s:3},{t:"Ikut dengan modal kecil", s:2},{t:"Ikut dan merekrut rekan lain", s:1}], ex:"Arisan berantai berbasis rekrutmen adalah skema piramida ilegal; ASN tidak boleh terlibat."},
{id:"TKP-2396", q:"Anda diminta menjadi saksi palsu dalam sidang disiplin rekan yang mangkir. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menjadi saksi palsu dan menyampaikan fakta sebenarnya", s:5},{t:"Menolak menjadi saksi", s:4},{t:"Menghindar dari panggilan sidang", s:3},{t:"Bersaksi samar agar tidak memberatkan", s:2},{t:"Bersaksi palsu membelanya", s:1}], ex:"Kesaksian palsu dalam sidang disiplin adalah pelanggaran hukum; integritas menuntut kejujuran."},
{id:"TKP-2397", q:"Seorang tokoh meminta Anda memfasilitasi dana bansos untuk dibagi ke pendukungnya saat kampanye. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak dan melaporkan politisasi bansos tersebut ke Bawaslu", s:5},{t:"Menolak permintaan itu", s:4},{t:"Menunda pencairan", s:3},{t:"Mencairkan sebagian untuk pendukungnya", s:2},{t:"Memfasilitasi sesuai permintaan", s:1}], ex:"Bansos untuk kampanye adalah politik uang terselubung; ASN wajib menolak dan melapor."},
{id:"TKP-2398", q:"Rekan Anda, Slamet, menyimpan buku panduan membuat bahan peledak di loker kantor. Sikap yang paling tepat adalah ....", opts:[{t:"Melaporkan temuan berbahaya tersebut segera ke pimpinan/aparat keamanan", s:5},{t:"Menegur Slamet dan memintanya menyingkirkan", s:4},{t:"Menjauhinya tanpa berbuat apa-apa", s:3},{t:"Diam karena takut", s:2},{t:"Ikut membaca panduannya", s:1}], ex:"Panduan bahan peledak di lingkungan kerja adalah ancaman terorisme; wajib dilaporkan segera."},
{id:"TKP-2399", q:"Atasan meminta Anda menghapus nama penerima bantuan yang kritis terhadapnya dari daftar. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak menghapus dan mempertahankan daftar sesuai kriteria yang sah", s:5},{t:"Menolak permintaan tersebut", s:4},{t:"Menunda perubahan daftar", s:3},{t:"Menghapus satu-dua nama", s:2},{t:"Menghapus sesuai perintah", s:1}], ex:"Daftar penerima bantuan berbasis kriteria, bukan like-dislike pimpinan; menghapus kritikus adalah penyalahgunaan wewenang."},
{id:"TKP-2400", q:"Di hari terakhir masa kerja, rekan Anda mengajak mengambil ATK dan inventaris kantor sebagai 'kenang-kenangan'. Sikap yang paling tepat adalah ....", opts:[{t:"Menolak tegas, menjelaskan itu aset negara, dan melaporkan bila ada yang mengambil", s:5},{t:"Menolak ikut mengambil", s:4},{t:"Tidak ikut tetapi tidak melarang", s:3},{t:"Mengambil sedikit sebagai kenangan", s:2},{t:"Ikut mengambil inventaris", s:1}], ex:"Inventaris kantor adalah aset negara hingga detik terakhir; mengambilnya adalah pencurian."}
];
